const LUKE_SECTIONS = {};

LUKE_SECTIONS["1"] = [{"title":"Úvod","range":"Lk 1,1–4","thoughts":[],"verses":[[1,"Mnozí se už pokusili sepsat zprávu o událostech, které se mezi námi naplnily,"],[2,"tak, jak nám je předali ti, kteří je od začátku sami viděli a potom sloužili slovu."],[3,"Proto jsem se i já rozhodl, vznešený Teofile, že všechno od začátku pečlivě prozkoumám a souvisle ti to sepíšu,"],[4,"abys poznal, jak spolehlivé je to, čemu jsi byl vyučován."]]},{"title":"Oznámení narození Jana Křtitele","range":"Lk 1,5–25","thoughts":[],"verses":[[5,"Za vlády judského krále Heroda žil kněz jménem Zachariáš z Abiášovy kněžské skupiny. Jeho žena Alžběta pocházela z rodu Áronova."],[6,"Oba žili před Bohem spravedlivě a věrně se řídili všemi Pánovými přikázáními a ustanoveními."],[7,"Neměli však děti, protože Alžběta byla neplodná, a oba už byli pokročilého věku."],[8,"Jednou, když byla na řadě jeho kněžská skupina, konal Zachariáš před Bohem kněžskou službu."],[9,"Podle kněžského zvyku na něj padl los, aby vstoupil do Pánova chrámu a zapálil kadidlo."],[10,"V době přinášení kadidla se venku modlil celý shromážděný lid."],[11,"Vtom se Zachariášovi ukázal Pánův anděl, který stál po pravé straně kadidlového oltáře."],[12,"Když ho Zachariáš uviděl, polekal se a zmocnil se ho strach."],[13,"Anděl mu však řekl: „Neboj se, Zachariáši. Tvá modlitba byla vyslyšena. Tvá žena Alžběta ti porodí syna a dáš mu jméno Jan."],[14,"Budeš z něj mít radost a veliké potěšení a z jeho narození se bude radovat mnoho lidí."],[15,"Bude totiž veliký před Pánem. Nebude pít víno ani jiný opojný nápoj a už od života své matky bude naplněn Duchem svatým."],[16,"Mnoho Izraelitů obrátí zpět k Pánu, jejich Bohu."],[17,"Půjde před ním v Eliášově duchu a moci. Obrátí srdce otců k dětem a neposlušné přivede k moudrosti spravedlivých. Tak připraví Pánu lid, který bude připraven.“"],[18,"Zachariáš se anděla zeptal: „Podle čeho poznám, že je to pravda? Jsem už starý a také má žena je pokročilého věku.“"],[19,"Anděl mu odpověděl: „Já jsem Gabriel a stojím před Bohem. Byl jsem poslán, abych s tebou mluvil a oznámil ti tuto dobrou zprávu."],[20,"Protože jsi však nevěřil mým slovům, která se ve svůj čas naplní, nebudeš moci mluvit až do dne, kdy se to stane.“"],[21,"Lidé mezitím čekali na Zachariáše a divili se, proč se v chrámu tak dlouho zdržuje."],[22,"Když vyšel ven, nemohl k nim promluvit. Pochopili tedy, že měl v chrámu vidění. Dorozumíval se s nimi jen posunky a zůstal němý."],[23,"Když skončily dny jeho služby, vrátil se domů."],[24,"Brzy potom jeho žena Alžběta otěhotněla. Pět měsíců se držela v ústraní a říkala:"],[25,"„Tohle pro mě udělal Pán. Teď na mě pohlédl a zbavil mě hanby mezi lidmi.“"]]},{"title":"Oznámení narození Ježíše","range":"Lk 1,26–38","thoughts":[],"verses":[[26,"V šestém měsíci poslal Bůh anděla Gabriela do galilejského města Nazaret."],[27,"Poslal ho k panně zasnoubené muži jménem Josef, který pocházel z Davidova rodu. Ta panna se jmenovala Marie."],[28,"Anděl k ní přišel a řekl: „Buď zdráva, ty, které se dostalo veliké milosti. Pán je s tebou.“"],[29,"Marie se nad jeho slovy zarazila a přemýšlela, co má takový pozdrav znamenat."],[30,"Anděl jí řekl: „Neboj se, Marie, protože jsi našla milost u Boha."],[31,"Otěhotníš, porodíš syna a dáš mu jméno Ježíš."],[32,"Bude veliký a bude nazýván Synem Nejvyššího. Pán Bůh mu dá trůn jeho otce Davida."],[33,"Bude navěky kralovat nad Jákobovým rodem a jeho království nebude mít konec.“"],[34,"Marie se anděla zeptala: „Jak se to může stát, když nežiji s mužem?“"],[35,"Anděl jí odpověděl: „Sestoupí na tebe Duch svatý a moc Nejvyššího tě zastíní. Proto také dítě, které se narodí, bude svaté a bude nazýváno Božím Synem."],[36,"Podívej, i tvá příbuzná Alžběta čeká ve svém stáří syna. Ta, o které se říkalo, že je neplodná, je už v šestém měsíci."],[37,"Pro Boha totiž není nic nemožné.“"],[38,"Marie řekla: „Jsem Pánova služebnice. Ať se mi stane podle tvého slova.“ Potom od ní anděl odešel."]]},{"title":"Marie navštěvuje Alžbětu","range":"Lk 1,39–56","thoughts":[],"verses":[[39,"V těch dnech se Marie vydala na cestu a spěchala do jednoho města v judských horách."],[40,"Vešla do Zachariášova domu a pozdravila Alžbětu."],[41,"Jakmile Alžběta uslyšela Mariin pozdrav, dítě v jejím těle se pohnulo radostí a Alžběta byla naplněna Duchem svatým."],[42,"Hlasitě zvolala: „Požehnaná jsi mezi ženami a požehnané je dítě, které nosíš."],[43,"Jak se mi dostalo té cti, že ke mně přichází matka mého Pána?"],[44,"Jakmile jsem zaslechla tvůj pozdrav, dítě v mém těle se radostí pohnulo."],[45,"Blaze té, která uvěřila, že se splní to, co jí Pán řekl.“"],[46,"Marie řekla: „Má duše oslavuje Pána"],[47,"a můj duch se raduje v Bohu, mém Zachránci,"],[48,"protože pohlédl na poníženost své služebnice. Od této chvíle mě budou všechny generace nazývat blahoslavenou,"],[49,"protože Mocný pro mě udělal veliké věci. Jeho jméno je svaté"],[50,"a jeho milosrdenství trvá od generace ke generaci pro ty, kdo před ním mají úctu."],[51,"Svou mocnou paží vykonal veliké věci a rozehnal ty, kdo jsou pyšní ve svých srdcích."],[52,"Mocné sesadil z trůnů a ponížené pozvedl."],[53,"Hladové nasytil dobrými věcmi a bohaté poslal pryč s prázdnou."],[54,"Ujal se Izraele, svého služebníka, a nezapomněl na své milosrdenství,"],[55,"jak slíbil našim otcům, Abrahamovi a jeho potomstvu navěky.“"],[56,"Marie zůstala u Alžběty asi tři měsíce a potom se vrátila domů."]]},{"title":"Narození Jana Křtitele","range":"Lk 1,57–66","thoughts":[],"verses":[[57,"Alžbětě se naplnil čas porodu a porodila syna."],[58,"Její sousedé a příbuzní uslyšeli, jak veliké milosrdenství jí Pán prokázal, a radovali se s ní."],[59,"Osmého dne přišli dítě obřezat a chtěli mu dát jméno Zachariáš po jeho otci."],[60,"Jeho matka však řekla: „Ne. Bude se jmenovat Jan.“"],[61,"Namítli jí: „Vždyť nikdo z tvých příbuzných se tak nejmenuje.“"],[62,"Posunky se tedy ptali jeho otce, jaké jméno chce dítěti dát."],[63,"Zachariáš si vyžádal tabulku a napsal: „Jeho jméno je Jan.“ Všichni se tomu podivili."],[64,"V té chvíli se mu otevřela ústa, jazyk se mu uvolnil a začal mluvit a chválit Boha."],[65,"Všech jejich sousedů se zmocnila posvátná bázeň a po celém judském pohoří se o těchto událostech mluvilo."],[66,"Všichni, kdo o tom slyšeli, si to uchovávali v srdci a říkali si: „Co z toho dítěte asi bude?“ Bylo totiž zřejmé, že Pán je s ním."]]},{"title":"Zachariášův chvalozpěv","range":"Lk 1,67–80","thoughts":[],"verses":[[67,"Jeho otec Zachariáš byl naplněn Duchem svatým a prorokoval:"],[68,"„Požehnaný je Pán, Bůh Izraele, protože přišel ke svému lidu a přinesl mu vykoupení."],[69,"V domě svého služebníka Davida nám dal mocného Zachránce,"],[70,"jak od dávných časů slíbil ústy svých svatých proroků:"],[71,"že nás zachrání před našimi nepřáteli a z rukou všech, kdo nás nenávidí."],[72,"Tak projevil milosrdenství našim otcům a připomněl svou svatou smlouvu,"],[73,"přísahu, kterou dal našemu otci Abrahamovi."],[74,"Slíbil, že nás vysvobodí z rukou nepřátel, abychom mu mohli beze strachu sloužit"],[75,"ve svatosti a spravedlnosti před ním po všechny své dny."],[76,"A ty, dítě, budeš nazýváno prorokem Nejvyššího, protože půjdeš před Pánem a budeš mu připravovat cestu."],[77,"Jeho lidu dáš poznat záchranu, která přichází odpuštěním jejich hříchů."],[78,"To všechno přichází z hlubokého milosrdenství našeho Boha. Díky němu nás navštíví světlo přicházející shůry,"],[79,"aby zazářilo těm, kdo žijí v temnotě a ve stínu smrti, a vedlo naše kroky na cestu pokoje.“"],[80,"Dítě rostlo a sílilo v duchu. Žilo v pustině až do dne, kdy veřejně vystoupilo před Izraelem."]]}];

LUKE_SECTIONS["2"] = [{"title":"Narození Ježíše","range":"Lk 2,1–20","thoughts":[],"verses":[[1,"V těch dnech vydal císař Augustus nařízení, aby bylo provedeno sčítání obyvatel celé říše."],[2,"Toto první sčítání se konalo v době, kdy Sýrii spravoval Quirinius."],[3,"Všichni se šli dát zapsat, každý do svého města."],[4,"Také Josef se vydal z galilejského Nazareta do Judska, do Davidova města zvaného Betlém, protože pocházel z Davidova rodu."],[5,"Šel se dát zapsat spolu s Marií, svou snoubenkou, která čekala dítě."],[6,"Když byli v Betlémě, přišel čas jejího porodu."],[7,"Porodila svého prvorozeného syna, zavinula ho do plenek a položila do jeslí, protože pro ně nebylo místo v ubytování."],[8,"V té krajině byli pastýři, kteří nocovali venku a hlídali svá stáda."],[9,"Najednou se před nimi objevil Pánův anděl a ozářila je Pánova sláva. Pastýři se velmi polekali."],[10,"Anděl jim řekl: „Nebojte se. Přináším vám dobrou zprávu o veliké radosti, která je určena všemu lidu."],[11,"Dnes se vám v Davidově městě narodil Zachránce, Mesiáš a Pán."],[12,"A toto vám bude znamením: Najdete dítě zavinuté do plenek a položené v jeslích.“"],[13,"Vtom se k andělovi přidalo veliké množství nebeských zástupů. Chválili Boha a říkali:"],[14,"„Sláva Bohu na výsostech a na zemi pokoj lidem, v nichž má zalíbení.“"],[15,"Když od nich andělé odešli do nebe, pastýři si řekli: „Pojďme do Betléma a podívejme se na to, co se stalo a co nám Pán oznámil.“"],[16,"Rychle se tam vydali a našli Marii, Josefa i dítě, které leželo v jeslích."],[17,"Když je uviděli, vyprávěli, co jim bylo o tom dítěti řečeno."],[18,"Všichni, kdo jejich vyprávění slyšeli, se tomu divili."],[19,"Marie si však všechna ta slova uchovávala a přemýšlela o nich ve svém srdci."],[20,"Pastýři se potom vrátili. Oslavovali a chválili Boha za všechno, co slyšeli a viděli, protože to bylo přesně tak, jak jim bylo řečeno."]]},{"title":"Ježíš je přinesen do chrámu","range":"Lk 2,21–40","thoughts":[],"verses":[[21,"Když uplynulo osm dní a dítě mělo být obřezáno, dostalo jméno Ježíš, jak ho nazval anděl ještě před jeho početím."],[22,"Když podle Mojžíšova zákona uplynula doba očišťování, přinesli Ježíše do Jeruzaléma, aby ho představili Pánu."],[23,"V Pánově zákoně je totiž napsáno: „Každý prvorozený syn bude zasvěcen Pánu.“"],[24,"Zároveň přinesli oběť, jak stanoví Pánův zákon: pár hrdliček nebo dvě holoubata."],[25,"V Jeruzalémě tehdy žil muž jménem Simeon. Byl spravedlivý a zbožný, očekával útěchu Izraele a byl s ním Duch svatý."],[26,"Duch svatý mu zjevil, že nezemře, dokud neuvidí Pánova Mesiáše."],[27,"Veden Duchem přišel Simeon do chrámu právě ve chvíli, kdy rodiče přinášeli malého Ježíše, aby s ním vykonali to, co předepisoval Zákon."],[28,"Simeon vzal dítě do náruče, chválil Boha a řekl:"],[29,"„Teď už, Pane, můžeš svého služebníka podle svého slova propustit v pokoji,"],[30,"protože mé oči viděly tvou záchranu,"],[31,"kterou jsi připravil před očima všech národů:"],[32,"světlo, které tě zjeví národům, a slávu tvého lidu Izraele.“"],[33,"Ježíšův otec a matka se divili tomu, co se o něm říkalo."],[34,"Simeon jim požehnal a Marii, jeho matce, řekl: „Toto dítě je určeno k pádu i povstání mnoha lidí v Izraeli a bude znamením, kterému budou odporovat."],[35,"I tvou vlastní duší pronikne meč. Tak vyjdou najevo myšlenky mnoha srdcí.“"],[36,"Byla tam také prorokyně Anna, dcera Fanuelova z kmene Ašer. Byla už velmi stará. Po svatbě žila se svým mužem sedm let"],[37,"a potom zůstala vdovou až do svých čtyřiaosmdesáti let. Téměř neopouštěla chrám a dnem i nocí sloužila Bohu postem a modlitbami."],[38,"Právě v tu chvíli přišla, vzdávala Bohu díky a mluvila o Ježíši všem, kdo očekávali vykoupení Jeruzaléma."],[39,"Když Josef s Marií splnili všechno, co ukládal Pánův zákon, vrátili se do Galileje, do svého města Nazareta."],[40,"Dítě rostlo a sílilo, bylo plné moudrosti a spočívala na něm Boží milost."]]},{"title":"Dvanáctiletý Ježíš v chrámu","range":"Lk 2,41–52","thoughts":[],"verses":[[41,"Ježíšovi rodiče chodili každý rok do Jeruzaléma na velikonoční svátky."],[42,"Když bylo Ježíšovi dvanáct let, vydali se tam jako obvykle na svátky."],[43,"Po skončení svátečních dnů se vraceli domů, ale chlapec Ježíš zůstal v Jeruzalémě. Jeho rodiče o tom nevěděli."],[44,"Mysleli si, že jde někde mezi ostatními poutníky, a tak urazili celý den cesty. Potom ho začali hledat mezi příbuznými a známými."],[45,"Když ho nenašli, vrátili se do Jeruzaléma a hledali ho tam."],[46,"Po třech dnech ho našli v chrámu. Seděl mezi učiteli, poslouchal je a kladl jim otázky."],[47,"Všichni, kdo ho slyšeli, žasli nad jeho porozuměním a odpověďmi."],[48,"Když ho rodiče uviděli, byli ohromeni. Jeho matka mu řekla: „Synu, proč jsi nám to udělal? Tvůj otec a já jsme tě s úzkostí hledali.“"],[49,"Ježíš jim odpověděl: „Proč jste mě hledali? Nevěděli jste, že musím být tam, kde jde o mého Otce?“"],[50,"Oni však nepochopili, co jim tím chtěl říct."],[51,"Potom se s nimi vrátil do Nazareta a poslouchal je. Jeho matka si všechna ta slova uchovávala v srdci."],[52,"Ježíš rostl v moudrosti i věku a získával stále větší přízeň u Boha i u lidí."]]}];

LUKE_SECTIONS["3"] = [{"title":"Jan Křtitel připravuje cestu","range":"Lk 3,1–20","thoughts":[],"verses":[[1,"V patnáctém roce vlády císaře Tiberia, když Pontius Pilát spravoval Judsko, Herodes vládl v Galileji, jeho bratr Filip v Itureji a Trachonitidě a Lysanias v Abiléně,"],[2,"v době velekněží Annáše a Kaifáše, promluvil Bůh na poušti k Janovi, synu Zachariášovu."],[3,"Jan procházel celým okolím Jordánu a hlásal křest obrácení na odpuštění hříchů."],[4,"Tak se naplňovalo to, co je napsáno v knize proroka Izajáše: „Hlas volajícího na poušti: Připravte cestu Pánu, narovnejte mu stezky."],[5,"Každé údolí bude vyplněno, každá hora a pahorek budou sníženy. Křivé cesty se narovnají a nerovné se vyhladí."],[6,"A všichni lidé uvidí Boží záchranu.“"],[7,"Zástupům, které přicházely, aby se od něj daly pokřtít, Jan říkal: „Hadí plemeno! Kdo vám namluvil, že uniknete přicházejícímu hněvu?"],[8,"Přinášejte ovoce, které odpovídá skutečnému obrácení. A nezačínejte si říkat: ‚Naším otcem je Abraham.‘ Říkám vám, že Bůh může Abrahamovi vzbudit děti i z těchto kamenů."],[9,"Sekera už leží u kořenů stromů. Každý strom, který nenese dobré ovoce, bude poražen a hozen do ohně.“"],[10,"Lidé se ho ptali: „Co tedy máme dělat?“"],[11,"Jan jim odpovídal: „Kdo má dva oděvy, ať se rozdělí s tím, kdo nemá žádný. A kdo má jídlo, ať udělá totéž.“"],[12,"Přišli se dát pokřtít i výběrčí daní a ptali se ho: „Mistře, co máme dělat my?“"],[13,"Řekl jim: „Nevybírejte víc, než kolik vám bylo stanoveno.“"],[14,"Ptali se ho také vojáci: „A co máme dělat my?“ Odpověděl jim: „Nikoho nevydírejte ani falešně neobviňujte a spokojte se se svým žoldem.“"],[15,"Lidé byli plní očekávání a všichni si v duchu říkali, jestli snad Jan není Mesiáš."],[16,"Jan proto všem odpověděl: „Já vás křtím vodou. Přichází však někdo mocnější než já. Nejsem hoden ani rozvázat řemínek jeho sandálů. On vás bude křtít Duchem svatým a ohněm."],[17,"V ruce má lopatu, aby důkladně vyčistil svůj mlat. Pšenici shromáždí do sýpky, ale plevy spálí neuhasitelným ohněm.“"],[18,"Takto i mnoha dalšími slovy Jan lidi povzbuzoval a hlásal jim dobrou zprávu."],[19,"Když však napomínal vládce Heroda kvůli Herodiadě, ženě jeho bratra, a také kvůli všemu zlému, co Herodes dělal,"],[20,"Herodes ke všemu ostatnímu přidal ještě to, že nechal Jana zavřít do vězení."]]},{"title":"Ježíšův křest","range":"Lk 3,21–22","thoughts":[],"verses":[[21,"Když se dával křtít všechen lid, byl pokřtěn také Ježíš. Když se potom modlil, otevřelo se nebe"],[22,"a Duch svatý na něj sestoupil v tělesné podobě jako holubice. Z nebe zazněl hlas: „Ty jsi můj milovaný Syn, v tobě mám zalíbení.“"]]},{"title":"Ježíšův rodokmen","range":"Lk 3,23–38","thoughts":[],"verses":[[23,"Když Ježíš začínal své působení, bylo mu asi třicet let. Lidé ho pokládali za syna Josefa, syna Heliho,"],[24,"syna Matata, syna Léviho, syna Melchiho, syna Jannaje, syna Josefa,"],[25,"syna Matatiáše, syna Amose, syna Nahuma, syna Esliho, syna Naggaje,"],[26,"syna Maata, syna Matatiáše, syna Semeina, syna Josecha, syna Jody,"],[27,"syna Joanana, syna Resy, syna Zerubábela, syna Šealtiela, syna Neriho,"],[28,"syna Melchiho, syna Addiho, syna Kosama, syna Elmadama, syna Era,"],[29,"syna Jozua, syna Eliezera, syna Jorima, syna Matata, syna Léviho,"],[30,"syna Simeona, syna Judy, syna Josefa, syna Jonama, syna Eliakima,"],[31,"syna Meley, syna Menny, syna Mattaty, syna Nátana, syna Davida,"],[32,"syna Jišaje, syna Obéda, syna Bóaze, syna Salmona, syna Nachšona,"],[33,"syna Amínadaba, syna Admina, syna Arniho, syna Chesrona, syna Perese, syna Judy,"],[34,"syna Jákoba, syna Izáka, syna Abrahama, syna Teracha, syna Nachora,"],[35,"syna Serúga, syna Reúa, syna Pelega, syna Ébera, syna Šelacha,"],[36,"syna Kenana, syna Arpakšáda, syna Šéma, syna Noema, syna Lámecha,"],[37,"syna Metuzaléma, syna Henocha, syna Jereda, syna Mahalalela, syna Kenana,"],[38,"syna Enóše, syna Šéta, syna Adama, syna Božího."]]}];

LUKE_SECTIONS["4"] = [{"title":"Ježíšovo pokušení","range":"Lk 4,1–13","thoughts":[],"verses":[[1,"Ježíš se vrátil od Jordánu plný Ducha svatého a Duch ho vedl pouští."],[2,"Čtyřicet dní ho tam pokoušel ďábel. Po celou tu dobu nic nejedl, a když ty dny skončily, dostal hlad."],[3,"Ďábel mu řekl: „Jsi-li Boží Syn, řekni tomuto kameni, ať se promění v chléb.“"],[4,"Ježíš mu odpověděl: „Je napsáno: ‚Člověk nebude žít jen z chleba.‘“"],[5,"Potom ho ďábel vyvedl vzhůru a v jediném okamžiku mu ukázal všechna království světa."],[6,"Řekl mu: „Dám ti všechnu jejich moc a slávu. Byla mi svěřena a mohu ji dát, komu chci."],[7,"Když se mi tedy pokloníš, všechno bude tvoje.“"],[8,"Ježíš mu odpověděl: „Je napsáno: ‚Pánu, svému Bohu, se budeš klanět a jen jemu budeš sloužit.‘“"],[9,"Pak ho ďábel zavedl do Jeruzaléma, postavil ho na vrchol chrámu a řekl: „Jsi-li Boží Syn, vrhni se odtud dolů."],[10,"Vždyť je napsáno: ‚Svým andělům přikáže, aby tě chránili,‘"],[11,"a také: ‚Ponesou tě na rukou, abys nenarazil nohou o kámen.‘“"],[12,"Ježíš mu odpověděl: „Také je řečeno: ‚Nebudeš pokoušet Pána, svého Boha.‘“"],[13,"Když ďábel vyzkoušel všechna pokušení, na nějaký čas od Ježíše odešel."]]},{"title":"Ježíš začíná působit v Galileji","range":"Lk 4,14–15","thoughts":[],"verses":[[14,"Ježíš se v moci Ducha vrátil do Galileje a zpráva o něm se rozšířila po celém okolí."],[15,"Učil v jejich synagogách a všichni o něm mluvili s uznáním."]]},{"title":"Ježíš v Nazaretě","range":"Lk 4,16–30","thoughts":[],"verses":[[16,"Ježíš přišel do Nazareta, kde vyrůstal. V sobotu šel jako obvykle do synagogy a postavil se, aby četl."],[17,"Podali mu svitek proroka Izajáše. Rozvinul ho a našel místo, kde bylo napsáno:"],[18,"„Duch Pána je nade mnou, protože mě pomazal, abych přinesl dobrou zprávu chudým. Poslal mě, abych vyhlásil zajatým propuštění, slepým navrácení zraku a utlačovaným svobodu,"],[19,"abych vyhlásil čas Pánovy přízně.“"],[20,"Potom svitek zavinul, vrátil ho služebníkovi a posadil se. Oči všech v synagoze se upíraly na něj."],[21,"Ježíš k nim začal mluvit: „Dnes se toto místo Písma naplnilo před vašima očima.“"],[22,"Všichni o něm mluvili příznivě a divili se slovům plným milosti, která vycházela z jeho úst. Říkali: „Není to přece Josefův syn?“"],[23,"Ježíš jim řekl: „Jistě mi připomenete přísloví: ‚Lékaři, uzdrav sám sebe.‘ A řeknete: ‚Udělej i tady ve svém rodném městě to, o čem jsme slyšeli, že se stalo v Kafarnaum.‘“"],[24,"Pokračoval: „Amen, říkám vám: Žádný prorok nebývá přijímán ve svém rodném kraji."],[25,"Řeknu vám pravdu: Za Eliášových dnů bylo v Izraeli mnoho vdov, když bylo nebe tři roky a šest měsíců zavřené a po celé zemi nastal veliký hlad."],[26,"Eliáš však nebyl poslán k žádné z nich, ale k vdově v Sareptě u Sidónu."],[27,"A za proroka Elíši bylo v Izraeli mnoho lidí s malomocenstvím, ale očištěn nebyl nikdo z nich, pouze Syřan Náman.“"],[28,"Když to lidé v synagoze slyšeli, naplnil je hněv."],[29,"Vstali, vyhnali Ježíše z města a vedli ho až na okraj srázu, na kterém jejich město stálo, aby ho shodili dolů."],[30,"On však prošel jejich středem a odešel."]]},{"title":"Uzdravení v Kafarnaum","range":"Lk 4,31–44","thoughts":[],"verses":[[31,"Potom sestoupil do galilejského města Kafarnaum a o sobotách tam učil."],[32,"Lidé žasli nad jeho učením, protože jeho slova měla autoritu."],[33,"V synagoze byl člověk posedlý nečistým duchem. Ten hlasitě vykřikl:"],[34,"„Co po nás chceš, Ježíši z Nazareta? Přišel jsi nás zničit? Vím, kdo jsi: Boží Svatý!“"],[35,"Ježíš mu přikázal: „Mlč a vyjdi z něj!“ Nečistý duch člověka před nimi srazil na zem a vyšel z něj, aniž mu ublížil."],[36,"Všichni byli ohromeni a říkali si mezi sebou: „Co je to za slovo? S autoritou a mocí přikazuje nečistým duchům a oni vycházejí!“"],[37,"Zpráva o Ježíšovi se šířila po celém okolí."],[38,"Ježíš odešel ze synagogy a vstoupil do Šimonova domu. Šimonovu tchyni trápila vysoká horečka, a tak ho prosili, aby jí pomohl."],[39,"Ježíš se nad ní sklonil, přikázal horečce a ta ji opustila. Žena hned vstala a začala je obsluhovat."],[40,"Když zapadalo slunce, přiváděli k Ježíšovi všichni své nemocné, ať trpěli jakoukoli nemocí. Na každého vkládal ruce a uzdravoval je."],[41,"Z mnoha lidí také vycházeli zlí duchové a křičeli: „Ty jsi Boží Syn!“ Ježíš je však napomínal a nedovoloval jim mluvit, protože věděli, že je Mesiáš."],[42,"Když se rozednilo, odešel Ježíš na opuštěné místo. Zástupy ho hledaly, a když ho našly, snažily se ho zadržet, aby od nich neodcházel."],[43,"On jim však řekl: „Také ostatním městům musím hlásat dobrou zprávu o Božím království, protože k tomu jsem byl poslán.“"],[44,"A dál kázal v synagogách po celé zemi."]]}];

LUKE_SECTIONS["5"] = [{"title":"Povolání prvních učedníků","range":"Lk 5,1–11","thoughts":[],"verses":[[1,"Jednou se na Ježíše tlačil zástup, protože lidé chtěli slyšet Boží slovo. Ježíš stál u Genezaretského jezera."],[2,"U břehu uviděl dvě lodě. Rybáři z nich vystoupili a prali sítě."],[3,"Ježíš nastoupil do jedné z lodí, která patřila Šimonovi, a požádal ho, aby trochu odrazil od břehu. Potom se posadil a z lodi učil zástupy."],[4,"Když domluvil, řekl Šimonovi: „Zajeď na hlubinu a spusťte sítě k lovu.“"],[5,"Šimon odpověděl: „Mistře, celou noc jsme se namáhali a nic jsme nechytili. Ale na tvé slovo sítě spustím.“"],[6,"Když to udělali, chytili takové množství ryb, že se jim sítě začaly trhat."],[7,"Dali proto znamení svým společníkům v druhé lodi, aby jim přijeli pomoct. Ti přijeli a naplnili obě lodě tak, že se téměř potápěly."],[8,"Když to Šimon Petr uviděl, padl Ježíšovi k nohám a řekl: „Odejdi ode mě, Pane, protože jsem hříšný člověk.“"],[9,"Jeho i všechny, kdo byli s ním, totiž ohromilo množství ryb, které chytili."],[10,"Stejně na tom byli Jakub a Jan, synové Zebedeovi, Šimonovi společníci. Ježíš Šimonovi řekl: „Neboj se. Od této chvíle budeš získávat lidi.“"],[11,"Když přirazili s loděmi ke břehu, všechno opustili a šli za ním."]]},{"title":"Očištění malomocného","range":"Lk 5,12–16","thoughts":[],"verses":[[12,"Když byl Ježíš v jednom městě, objevil se tam muž postižený malomocenstvím. Jakmile Ježíše uviděl, padl před ním tváří k zemi a prosil: „Pane, jestli chceš, můžeš mě očistit.“"],[13,"Ježíš vztáhl ruku, dotkl se ho a řekl: „Chci. Buď čistý.“ V té chvíli malomocenství zmizelo."],[14,"Ježíš mu přikázal: „Nikomu o tom neříkej. Jdi se ukázat knězi a přines za své očištění oběť, kterou přikázal Mojžíš. Bude to pro ně svědectvím.“"],[15,"Zprávy o Ježíšovi se však šířily stále víc a scházely se k němu velké zástupy, aby ho poslouchaly a nechaly se uzdravit ze svých nemocí."],[16,"Ježíš se ale často uchyloval na opuštěná místa a tam se modlil."]]},{"title":"Uzdravení ochrnutého","range":"Lk 5,17–26","thoughts":[],"verses":[[17,"Jednoho dne Ježíš učil a seděli tam také farizeové a učitelé Zákona, kteří přišli ze všech galilejských a judských vesnic i z Jeruzaléma. Pánova moc působila, aby Ježíš uzdravoval."],[18,"Vtom přinesli muži na nosítkách ochrnutého člověka. Snažili se ho dostat dovnitř a položit před Ježíše."],[19,"Kvůli zástupu však nenašli cestu dovnitř. Vystoupili proto na střechu, rozebrali její část a spustili nemocného i s nosítky doprostřed místnosti přímo před Ježíše."],[20,"Když Ježíš viděl jejich víru, řekl: „Člověče, tvé hříchy jsou ti odpuštěny.“"],[21,"Učitelé Zákona a farizeové začali přemýšlet: „Kdo je ten člověk, že se tak rouhá? Kdo může odpouštět hříchy kromě samotného Boha?“"],[22,"Ježíš poznal jejich myšlenky a řekl jim: „O čem to ve svých srdcích přemýšlíte?"],[23,"Co je snazší říct: ‚Tvé hříchy jsou ti odpuštěny,‘ nebo: ‚Vstaň a choď‘?"],[24,"Abyste ale věděli, že Syn člověka má na zemi pravomoc odpouštět hříchy...“ Potom řekl ochrnutému: „Říkám ti: Vstaň, vezmi si svá nosítka a jdi domů.“"],[25,"Muž před nimi okamžitě vstal, vzal si to, na čem ležel, a odešel domů. Přitom oslavoval Boha."],[26,"Všichni byli ohromeni a oslavovali Boha. Naplnila je posvátná bázeň a říkali: „Dnes jsme viděli něco neuvěřitelného.“"]]},{"title":"Povolání Léviho","range":"Lk 5,27–32","thoughts":[],"verses":[[27,"Potom Ježíš vyšel ven a uviděl výběrčího daní jménem Lévi, jak sedí na celnici. Řekl mu: „Pojď za mnou.“"],[28,"Lévi vstal, všechno tam nechal a šel za ním."],[29,"Potom pro Ježíše uspořádal ve svém domě velkou hostinu. U stolu s nimi sedělo mnoho výběrčích daní a dalších lidí."],[30,"Farizeové a jejich učitelé Zákona si stěžovali Ježíšovým učedníkům: „Proč jíte a pijete s výběrčími daní a hříšníky?“"],[31,"Ježíš jim odpověděl: „Lékaře nepotřebují zdraví, ale nemocní."],[32,"Nepřišel jsem volat spravedlivé, ale hříšníky, aby se obrátili.“"]]},{"title":"Otázka půstu","range":"Lk 5,33–39","thoughts":[],"verses":[[33,"Řekli mu: „Janovi učedníci se často postí a modlí, stejně jako učedníci farizeů. Tvoji ale jedí a pijí.“"],[34,"Ježíš jim odpověděl: „Můžete snad nutit svatební hosty, aby se postili, dokud je ženich s nimi?"],[35,"Přijdou však dny, kdy jim bude ženich vzat. V těch dnech se budou postit.“"],[36,"Řekl jim také podobenství: „Nikdo neodtrhne kus z nového oděvu, aby jím záplatoval starý. Jinak poškodí nový oděv a záplata z nového se ke starému ani nebude hodit."],[37,"Nikdo také nelije nové víno do starých měchů. Nové víno by je roztrhlo, vyteklo by a měchy by se zničily."],[38,"Nové víno se musí nalít do nových měchů."],[39,"A kdo pil staré víno, nechce hned nové, protože říká: ‚Staré je dobré.‘“"]]}];

LUKE_SECTIONS["6"] = [{"title":"Ježíš a sobota","range":"Lk 6,1–11","thoughts":[],"verses":[[1,"Jednou v sobotu procházel Ježíš obilím. Jeho učedníci trhali klasy, mnuli je v rukou a jedli zrní."],[2,"Někteří farizeové se jich zeptali: „Proč děláte v sobotu něco, co není dovoleno?“"],[3,"Ježíš jim odpověděl: „Nečetli jste, co udělal David, když měl hlad on i jeho muži?"],[4,"Vešel do Božího domu, vzal posvátné chleby, jedl je a dal také svým mužům, přestože je smějí jíst jen kněží.“"],[5,"A dodal: „Syn člověka je pánem i nad sobotou.“"],[6,"Jinou sobotu vešel do synagogy a učil. Byl tam člověk, který měl ochrnutou pravou ruku."],[7,"Učitelé Zákona a farizeové Ježíše pozorně sledovali, jestli bude v sobotu uzdravovat, aby našli důvod k obžalobě."],[8,"Ježíš však znal jejich myšlenky. Řekl muži s ochrnutou rukou: „Vstaň a postav se doprostřed.“ Muž vstal a postavil se tam."],[9,"Ježíš jim řekl: „Ptám se vás: Je v sobotu dovoleno dělat dobro, nebo zlo? Zachránit život, nebo ho zničit?“"],[10,"Rozhlédl se po všech kolem a řekl tomu muži: „Natáhni ruku.“ Udělal to a jeho ruka byla zase zdravá."],[11,"Je však zachvátil vztek a začali se mezi sebou radit, co by mohli proti Ježíšovi podniknout."]]},{"title":"Vyvolení Dvanácti","range":"Lk 6,12–16","thoughts":[],"verses":[[12,"V těch dnech Ježíš odešel na horu, aby se modlil. Celou noc strávil v modlitbě k Bohu."],[13,"Když se rozednilo, zavolal své učedníky a vybral z nich dvanáct, které také nazval apoštoly:"],[14,"Šimona, kterému dal jméno Petr, jeho bratra Ondřeje, Jakuba, Jana, Filipa, Bartoloměje,"],[15,"Matouše, Tomáše, Jakuba Alfeova, Šimona zvaného Zélóta,"],[16,"Judu Jakubova a Jidáše Iškariotského, který se později stal zrádcem."]]},{"title":"Ježíš učí a uzdravuje","range":"Lk 6,17–19","thoughts":[],"verses":[[17,"Ježíš s nimi sestoupil a zastavil se na rovině. Byl tam velký zástup jeho učedníků a mnoho lidí z celého Judska, z Jeruzaléma i z pobřeží kolem Týru a Sidónu. Přišli ho poslouchat a nechat se uzdravit ze svých nemocí."],[18,"Uzdravováni byli i ti, které trápili nečistí duchové."],[19,"Všichni v zástupu se snažili Ježíše dotknout, protože z něj vycházela moc a uzdravovala je všechny."]]},{"title":"Blahoslavenství a běda","range":"Lk 6,20–26","thoughts":[],"verses":[[20,"Ježíš se podíval na své učedníky a řekl: „Blaze vám chudým, protože vám patří Boží království."],[21,"Blaze vám, kteří teď hladovíte, protože budete nasyceni. Blaze vám, kteří teď pláčete, protože se budete smát."],[22,"Blaze vám, když vás lidé budou kvůli Synu člověka nenávidět, odmítat, urážet a vaše jméno zavrhnou jako něco zlého."],[23,"V ten den se radujte a jásejte, protože vás v nebi čeká veliká odměna. Stejně totiž jejich předkové zacházeli s proroky."],[24,"Ale běda vám bohatým, protože už jste svou útěchu dostali."],[25,"Běda vám, kteří jste teď nasyceni, protože budete hladovět. Běda vám, kteří se teď smějete, protože budete truchlit a plakat."],[26,"Běda vám, když o vás budou všichni lidé mluvit dobře. Stejně totiž jejich předkové mluvili o falešných prorocích."]]},{"title":"Láska k nepřátelům","range":"Lk 6,27–36","thoughts":[],"verses":[[27,"„Vám, kteří mě posloucháte, však říkám: Milujte své nepřátele a dělejte dobře těm, kdo vás nenávidí."],[28,"Žehnejte těm, kdo vás proklínají, a modlete se za ty, kdo vám ubližují."],[29,"Když tě někdo udeří do jedné tváře, nastav mu i druhou. Kdo ti vezme plášť, tomu nebraň vzít si ani košili."],[30,"Každému, kdo tě prosí, dej. A když ti někdo vezme, co je tvoje, nežádej to zpátky."],[31,"Jak chcete, aby lidé jednali s vámi, tak jednejte vy s nimi."],[32,"Když milujete jen ty, kdo milují vás, jakou zásluhu za to čekáte? Vždyť i hříšníci milují ty, kdo milují je."],[33,"A když děláte dobře jen těm, kdo dělají dobře vám, jakou zásluhu za to čekáte? Totéž dělají i hříšníci."],[34,"A když půjčujete jen těm, od kterých očekáváte, že vám to vrátí, jakou zásluhu za to čekáte? I hříšníci půjčují hříšníkům, aby dostali zpět totéž."],[35,"Vy však milujte své nepřátele, dělejte dobro a půjčujte bez očekávání, že něco dostanete zpět. Vaše odměna bude veliká a budete syny Nejvyššího, protože on je dobrý i k nevděčným a zlým."],[36,"Buďte milosrdní, jako je milosrdný váš Otec."]]},{"title":"Nesuďte","range":"Lk 6,37–42","thoughts":[],"verses":[[37,"„Nesuďte, a nebudete souzeni. Neodsuzujte, a nebudete odsouzeni. Odpouštějte, a bude vám odpuštěno."],[38,"Dávejte, a bude vám dáno. Do klína vám nasypou dobrou míru, natlačenou, protřesenou a vrchovatou. Jakou mírou měříte, takovou bude naměřeno vám.“"],[39,"Řekl jim také podobenství: „Může slepý vést slepého? Nespadnou oba do jámy?"],[40,"Žák není nad svého učitele. Když však dokončí výcvik, bude jako jeho učitel."],[41,"Proč vidíš třísku v oku svého bratra, ale trámu ve vlastním oku si nevšímáš?"],[42,"Jak můžeš svému bratru říct: ‚Bratře, dovol, ať ti vytáhnu třísku z oka,‘ když sám nevidíš trám ve svém oku? Pokrytče! Nejdřív vyndej trám ze svého oka a potom uvidíš jasně, abys mohl vytáhnout třísku z oka svého bratra."]]},{"title":"Strom a jeho ovoce","range":"Lk 6,43–45","thoughts":[],"verses":[[43,"„Dobrý strom nenese špatné ovoce a špatný strom nenese dobré ovoce."],[44,"Každý strom se pozná podle vlastního ovoce. Fíky se přece nesbírají z trní ani hrozny z bodláčí."],[45,"Dobrý člověk vynáší dobro z dobrého pokladu svého srdce a zlý člověk vynáší zlo ze zlého. Ústa totiž mluví o tom, čím je srdce naplněné."]]},{"title":"Dům na skále","range":"Lk 6,46–49","thoughts":[],"verses":[[46,"„Proč mi říkáte: ‚Pane, Pane,‘ a přitom neděláte, co říkám?"],[47,"Ukážu vám, komu se podobá každý, kdo ke mně přichází, slyší má slova a podle nich jedná."],[48,"Podobá se člověku, který stavěl dům. Kopal hluboko a položil základy na skále. Když přišla povodeň a proud udeřil do toho domu, nemohl jím otřást, protože byl dobře postaven."],[49,"Kdo však má slova slyší a nejedná podle nich, podobá se člověku, který postavil dům přímo na zemi bez základů. Když do něj udeřil proud, dům se hned zřítil a jeho pád byl veliký.“"]]}];

LUKE_SECTIONS["7"] = [{"title":"Víra setníka","range":"Lk 7,1–10","thoughts":[],"verses":[[1,"Když Ježíš dokončil svou řeč k lidem, odešel do Kafarnaum."],[2,"Jeden setník tam měl služebníka, kterého si velmi vážil. Ten byl vážně nemocný a umíral."],[3,"Když setník uslyšel o Ježíšovi, poslal k němu několik židovských starších s prosbou, aby přišel a jeho služebníka zachránil."],[4,"Přišli k Ježíšovi a naléhavě ho prosili: „Ten člověk si zaslouží, abys mu pomohl."],[5,"Má rád náš národ a dokonce nám postavil synagogu.“"],[6,"Ježíš se tedy vydal s nimi. Když už nebyl daleko od domu, poslal mu setník naproti své přátele se vzkazem: „Pane, nenamáhej se. Nejsem hoden, abys vstoupil pod mou střechu."],[7,"Proto jsem se ani nepovažoval za hodného přijít k tobě osobně. Stačí, když řekneš slovo, a můj služebník bude uzdraven."],[8,"Vždyť i já podléhám autoritě a zároveň mám pod sebou vojáky. Jednomu řeknu: ‚Jdi,‘ a jde. Jinému: ‚Přijď,‘ a přijde. A svému služebníkovi: ‚Udělej tohle,‘ a udělá to.“"],[9,"Když to Ježíš uslyšel, podivil se mu. Obrátil se k zástupu, který ho následoval, a řekl: „Říkám vám, ani v Izraeli jsem nenašel tak velikou víru.“"],[10,"Když se poslové vrátili do domu, našli služebníka zdravého."]]},{"title":"Vzkříšení syna vdovy v Naim","range":"Lk 7,11–17","thoughts":[],"verses":[[11,"Brzy potom se Ježíš vydal do města zvaného Naim. Šli s ním jeho učedníci a velký zástup."],[12,"Když se přiblížil k městské bráně, právě vynášeli mrtvého. Byl to jediný syn své matky, která byla vdova. Doprovázel ji velký zástup lidí z města."],[13,"Když ji Pán uviděl, bylo mu jí hluboce líto a řekl jí: „Neplač.“"],[14,"Přistoupil k márám a dotkl se jich. Ti, kdo je nesli, se zastavili. Ježíš řekl: „Mladíku, říkám ti, vstaň!“"],[15,"Mrtvý se posadil a začal mluvit. Ježíš ho vrátil jeho matce."],[16,"Všech se zmocnila posvátná bázeň. Oslavovali Boha a říkali: „Povstal mezi námi veliký prorok“ a „Bůh přišel na pomoc svému lidu.“"],[17,"Zpráva o Ježíšovi se rozšířila po celém Judsku i po okolní krajině."]]},{"title":"Jan Křtitel a Ježíš","range":"Lk 7,18–35","thoughts":[],"verses":[[18,"Janovi učedníci mu o všech těchto událostech vyprávěli. Jan si zavolal dva ze svých učedníků"],[19,"a poslal je k Pánu s otázkou: „Jsi ten, který má přijít, nebo máme čekat někoho jiného?“"],[20,"Když ti muži přišli k Ježíšovi, řekli: „Jan Křtitel nás k tobě poslal s otázkou: ‚Jsi ten, který má přijít, nebo máme čekat někoho jiného?‘“"],[21,"Právě v tu dobu Ježíš uzdravil mnoho lidí z nemocí a trápení, osvobodil je od zlých duchů a mnoha slepým vrátil zrak."],[22,"Potom poslům odpověděl: „Jděte a vyprávějte Janovi, co jste viděli a slyšeli: Slepí vidí, chromí chodí, lidé s malomocenstvím jsou očišťováni, hluší slyší, mrtví vstávají a chudým se hlásá dobrá zpráva."],[23,"A blaze tomu, kdo kvůli mně neztratí víru.“"],[24,"Když Janovi poslové odešli, začal Ježíš mluvit zástupům o Janovi: „Na co jste se šli podívat do pouště? Na rákos zmítaný větrem?"],[25,"Nebo co jste chtěli vidět? Člověka oblečeného do jemných šatů? Ti, kdo nosí nádherné oblečení a žijí v přepychu, jsou v královských palácích."],[26,"Tak co jste tedy vyšli vidět? Proroka? Ano, říkám vám, a dokonce někoho víc než proroka."],[27,"Právě o něm je napsáno: ‚Posílám před tebou svého posla, který ti připraví cestu.‘"],[28,"Říkám vám: Mezi těmi, kdo se narodili z ženy, není nikdo větší než Jan. A přesto i ten nejmenší v Božím království je větší než on.“"],[29,"Všichni lidé, kteří ho slyšeli, včetně výběrčích daní, uznali, že Bůh jedná správně, protože přijali Janův křest."],[30,"Farizeové a učitelé Zákona však Boží záměr pro sebe odmítli, protože se od Jana pokřtít nedali."],[31,"Ježíš pokračoval: „Ke komu tedy přirovnám lidi této generace? Komu se podobají?"],[32,"Jsou jako děti, které sedí na tržišti a volají jedna na druhou: ‚Hráli jsme vám do tance, a netancovali jste. Zpívali jsme vám smuteční píseň, a neplakali jste.‘"],[33,"Přišel Jan Křtitel, nejedl chléb a nepil víno, a vy říkáte: ‚Je posedlý.‘"],[34,"Přišel Syn člověka, jí a pije, a vy říkáte: ‚Podívejte na toho jedlíka a pijana, přítele výběrčích daní a hříšníků!‘"],[35,"Moudrost se však ukazuje jako správná na životě všech, kdo se jí řídí.“"]]},{"title":"Ježíš a hříšná žena","range":"Lk 7,36–50","thoughts":[],"verses":[[36,"Jeden z farizeů pozval Ježíše k jídlu. Ježíš tedy vešel do jeho domu a zaujal místo u stolu."],[37,"Ve městě žila žena známá jako hříšnice. Když se dozvěděla, že Ježíš jí v domě toho farizea, přinesla alabastrovou nádobku s vonným olejem."],[38,"Postavila se zezadu k jeho nohám a plakala. Slzami mu začala smáčet nohy, utírala je svými vlasy, líbala je a potírala vonným olejem."],[39,"Když to farizeus, který Ježíše pozval, viděl, pomyslel si: „Kdyby tenhle člověk byl prorok, věděl by, kdo a jaká je ta žena, která se ho dotýká. Vždyť je to hříšnice.“"],[40,"Ježíš mu řekl: „Šimone, chci ti něco říct.“ On odpověděl: „Pověz, Mistře.“"],[41,"Ježíš řekl: „Jeden věřitel měl dva dlužníky. Jeden mu dlužil pět set denárů a druhý padesát."],[42,"Ani jeden neměl čím zaplatit, a tak dluh odpustil oběma. Který z nich ho bude mít víc rád?“"],[43,"Šimon odpověděl: „Myslím, že ten, kterému odpustil víc.“ Ježíš řekl: „Správně jsi usoudil.“"],[44,"Potom se obrátil k ženě a Šimonovi řekl: „Vidíš tuto ženu? Přišel jsem do tvého domu a nedal jsi mi vodu na nohy. Ona mi je však smáčela slzami a utírala svými vlasy."],[45,"Ty jsi mě na přivítanou nepolíbil, ale ona od chvíle, kdy jsem přišel, nepřestala líbat mé nohy."],[46,"Ty jsi mi nepotřel hlavu olejem, ale ona potřela vonným olejem mé nohy."],[47,"Proto ti říkám: Její mnohé hříchy jsou odpuštěny, a proto projevuje tolik lásky. Komu se odpouští málo, ten málo miluje.“"],[48,"Potom ženě řekl: „Tvé hříchy jsou odpuštěny.“"],[49,"Ostatní hosté si mezi sebou začali říkat: „Kdo je ten člověk, že dokonce odpouští hříchy?“"],[50,"Ježíš ženě řekl: „Tvá víra tě zachránila. Jdi v pokoji.“"]]}];

LUKE_SECTIONS["8"] = [{"title":"Ženy, které doprovázely Ježíše","range":"Lk 8,1–3","thoughts":[],"verses":[[1,"Brzy potom Ježíš procházel městy a vesnicemi, kázal a přinášel dobrou zprávu o Božím království. Doprovázelo ho Dvanáct."],[2,"Byly s ním také některé ženy, které uzdravil od zlých duchů a nemocí: Marie zvaná Magdaléna, ze které vyšlo sedm zlých duchů,"],[3,"Jana, manželka Chuzy, správce Herodova domu, Zuzana a mnoho dalších. Tyto ženy je podporovaly ze svého majetku."]]},{"title":"Podobenství o rozsévači","range":"Lk 8,4–15","thoughts":[],"verses":[[4,"Když se scházel velký zástup a lidé k Ježíšovi přicházeli z různých měst, vyprávěl jim podobenství:"],[5,"„Rozsévač vyšel zasít své semeno. Když rozséval, některá zrna padla podél cesty. Lidé je pošlapali a ptáci je sezobali."],[6,"Jiná padla na skálu. Vyrostla, ale uschla, protože neměla vláhu."],[7,"Další padla mezi trní. Trní rostlo spolu s nimi a zadusilo je."],[8,"Jiná však padla do dobré půdy, vyrostla a přinesla stonásobnou úrodu.“ Potom Ježíš zvolal: „Kdo má uši k slyšení, ať poslouchá!“"],[9,"Jeho učedníci se ho ptali, co toto podobenství znamená."],[10,"Ježíš řekl: „Vám je dáno poznávat tajemství Božího království, ostatním jsou však podávána v podobenstvích, aby se dívali, a přesto neviděli, a poslouchali, a přesto nerozuměli."],[11,"Toto je význam podobenství: Semeno je Boží slovo."],[12,"Zrna podél cesty představují ty, kdo slovo slyší, ale potom přichází ďábel a bere jim je ze srdce, aby neuvěřili a nebyli zachráněni."],[13,"Zrna na skále představují ty, kdo slovo slyší a s radostí je přijmou, ale nemají kořeny. Nějakou dobu věří, ale v době zkoušky odpadnou."],[14,"To, co padlo mezi trní, představuje lidi, kteří slovo slyší, ale postupně je zadusí starosti, bohatství a životní požitky, takže jejich život nepřinese zralé ovoce."],[15,"Semeno v dobré půdě představuje ty, kdo slyší slovo, uchovávají je v dobrém a upřímném srdci a vytrvale přinášejí ovoce."]]},{"title":"Lampa a světlo","range":"Lk 8,16–18","thoughts":[],"verses":[[16,"„Nikdo nerozsvítí lampu a potom ji nepřikryje nádobou ani ji neschová pod postel. Postaví ji na stojan, aby ti, kdo přicházejí dovnitř, viděli světlo."],[17,"Není nic skrytého, co by jednou nebylo odhaleno, ani nic tajného, co by nebylo poznáno a nevyšlo najevo."],[18,"Dávejte tedy pozor, jak posloucháte. Kdo má, tomu bude přidáno. Kdo nemá, tomu bude vzato i to, o čem si myslí, že má.“"]]},{"title":"Ježíšova matka a bratři","range":"Lk 8,19–21","thoughts":[],"verses":[[19,"Přišla za ním jeho matka a bratři, ale kvůli zástupu se k němu nemohli dostat."],[20,"Někdo mu oznámil: „Tvoje matka a bratři stojí venku a chtějí tě vidět.“"],[21,"Ježíš jim odpověděl: „Moje matka a moji bratři jsou ti, kdo slyší Boží slovo a jednají podle něj.“"]]},{"title":"Utišení bouře","range":"Lk 8,22–25","thoughts":[],"verses":[[22,"Jednoho dne nastoupil Ježíš se svými učedníky do lodi a řekl jim: „Přeplavme se na druhou stranu jezera.“ Vypluli tedy."],[23,"Během plavby Ježíš usnul. Na jezero se snesla prudká bouře, loď se začala plnit vodou a ocitli se v nebezpečí."],[24,"Učedníci k němu přišli a probudili ho: „Mistře, Mistře, zahyneme!“ Ježíš vstal, přikázal větru a rozbouřeným vlnám, aby ustaly. Bouře se utišila a nastal klid."],[25,"Potom se jich zeptal: „Kde je vaše víra?“ Učedníci byli plní bázně a údivu a říkali si: „Kdo to vlastně je, že poroučí i větru a vodě a ony ho poslouchají?“"]]},{"title":"Uzdravení posedlého","range":"Lk 8,26–39","thoughts":[],"verses":[[26,"Dopluli do kraje Gerasenů na protějším břehu od Galileje."],[27,"Když Ježíš vystoupil na břeh, přišel mu naproti muž z města, který byl dlouhou dobu posedlý zlými duchy. Nenosil oblečení a nebydlel v domě, ale mezi hroby."],[28,"Když uviděl Ježíše, vykřikl, padl před ním a hlasitě řekl: „Co ode mě chceš, Ježíši, Synu nejvyššího Boha? Prosím tě, netrap mě!“"],[29,"Ježíš totiž nečistému duchu přikazoval, aby z toho člověka vyšel. Duch ho často ovládal. Lidé ho sice hlídali spoutaného řetězy a okovy, ale on pouta trhal a zlý duch ho hnal do pustiny."],[30,"Ježíš se ho zeptal: „Jak se jmenuješ?“ Odpověděl: „Legie,“ protože do něj vstoupilo mnoho zlých duchů."],[31,"Ti Ježíše prosili, aby jim nepřikazoval odejít do propasti."],[32,"Na svahu se tam páslo velké stádo prasat. Duchové Ježíše prosili, aby jim dovolil vejít do nich. Ježíš jim to dovolil."],[33,"Zlí duchové vyšli z člověka a vstoupili do prasat. Stádo se pak prudce rozběhlo ze svahu do jezera a utopilo se."],[34,"Když pasáci viděli, co se stalo, utekli a roznesli tu zprávu po městě i po okolí."],[35,"Lidé se přišli podívat, co se stalo. Když dorazili k Ježíšovi, našli muže, z něhož vyšli zlí duchové, jak oblečený a při zdravém rozumu sedí u Ježíšových nohou. Dostali strach."],[36,"Ti, kdo všechno viděli, jim vyprávěli, jak byl posedlý muž zachráněn."],[37,"Všichni lidé z okolí pak Ježíše prosili, aby od nich odešel, protože je ovládl veliký strach. Ježíš tedy nastoupil do lodi a vrátil se."],[38,"Muž, z něhož vyšli zlí duchové, ho prosil, aby směl jít s ním. Ježíš ho však poslal pryč se slovy:"],[39,"„Vrať se domů a vyprávěj, jak veliké věci pro tebe Bůh udělal.“ Muž tedy odešel a po celém městě vyprávěl, co pro něj Ježíš udělal."]]},{"title":"Jairova dcera a nemocná žena","range":"Lk 8,40–56","thoughts":[],"verses":[[40,"Když se Ježíš vrátil, zástup ho přivítal, protože na něj všichni čekali."],[41,"Vtom přišel muž jménem Jair, představený synagogy. Padl Ježíšovi k nohám a prosil ho, aby přišel do jeho domu."],[42,"Jeho jediná dcera, asi dvanáctiletá, totiž umírala. Když Ježíš šel, zástupy se na něj ze všech stran tlačily."],[43,"Byla tam také žena, která už dvanáct let trpěla krvácením. Za lékaře utratila celý svůj majetek, ale nikdo ji nedokázal uzdravit."],[44,"Přistoupila k Ježíšovi zezadu a dotkla se okraje jeho oděvu. V tu chvíli její krvácení přestalo."],[45,"Ježíš se zeptal: „Kdo se mě dotkl?“ Když to všichni popírali, Petr řekl: „Mistře, vždyť se na tebe ze všech stran tlačí zástupy.“"],[46,"Ježíš však řekl: „Někdo se mě dotkl. Poznal jsem, že ze mě vyšla moc.“"],[47,"Když žena pochopila, že nezůstala skrytá, rozechvělá přišla, padla před Ježíšem a před všemi lidmi řekla, proč se ho dotkla a jak byla okamžitě uzdravena."],[48,"Ježíš jí řekl: „Dcero, tvá víra tě zachránila. Jdi v pokoji.“"],[49,"Ještě když mluvil, přišel někdo z domu představeného synagogy a řekl: „Tvá dcera zemřela. Už Mistra neobtěžuj.“"],[50,"Ježíš to uslyšel a řekl Jairovi: „Neboj se. Jen věř a bude zachráněna.“"],[51,"Když přišel k domu, nedovolil nikomu vejít s ním kromě Petra, Jana, Jakuba a rodičů dítěte."],[52,"Všichni plakali a naříkali nad dívkou. Ježíš jim řekl: „Neplačte. Nezemřela, jen spí.“"],[53,"Posmívali se mu, protože věděli, že zemřela."],[54,"Ježíš ji však vzal za ruku a zavolal: „Děvče, vstaň!“"],[55,"Její život se vrátil a ona okamžitě vstala. Ježíš přikázal, aby jí dali něco k jídlu."],[56,"Její rodiče byli ohromeni. Ježíš jim však přikázal, aby nikomu neříkali, co se stalo."]]}];

LUKE_SECTIONS["9"] = [{"title":"Vyslání Dvanácti","range":"Lk 9,1–6","thoughts":[],"verses":[[1,"Ježíš svolal Dvanáct a dal jim sílu a pravomoc nad všemi zlými duchy i moc uzdravovat nemoci."],[2,"Potom je poslal hlásat Boží království a uzdravovat nemocné."],[3,"Řekl jim: „Na cestu si nic neberte: ani hůl, ani brašnu, ani chléb, ani peníze, ani náhradní oděv."],[4,"Do kteréhokoli domu vstoupíte, zůstaňte tam, dokud z toho místa neodejdete."],[5,"A kde vás nepřijmou, odejděte z toho města a setřeste si prach z nohou na svědectví proti nim.“"],[6,"Učedníci tedy vyšli a procházeli vesnicemi. Všude hlásali dobrou zprávu a uzdravovali."]]},{"title":"Herodes slyší o Ježíšovi","range":"Lk 9,7–9","thoughts":[],"verses":[[7,"Vládce Herodes se doslechl o všem, co se dělo, a nevěděl, co si o tom má myslet. Někteří totiž říkali, že Jan vstal z mrtvých,"],[8,"jiní, že se objevil Eliáš, a další, že vstal z mrtvých některý ze starých proroků."],[9,"Herodes řekl: „Jana jsem nechal popravit. Kdo je tedy ten člověk, o kterém slyším takové věci?“ A chtěl Ježíše vidět."]]},{"title":"Nasycení pěti tisíc","range":"Lk 9,10–17","thoughts":[],"verses":[[10,"Když se apoštolové vrátili, vyprávěli Ježíšovi všechno, co udělali. Vzal je s sebou a odešel do ústraní směrem k městu Betsaida."],[11,"Zástupy se to však dozvěděly a šly za ním. Ježíš je přijal, mluvil k nim o Božím království a uzdravoval ty, kdo to potřebovali."],[12,"Den se začal chýlit ke konci. Dvanáct k němu přišlo a řeklo: „Pošli zástup pryč, ať se rozejdou do okolních vesnic a usedlostí, najdou si nocleh a něco k jídlu. Tady jsme na opuštěném místě.“"],[13,"Ježíš jim odpověděl: „Dejte jim najíst vy.“ Řekli: „Máme jen pět chlebů a dvě ryby. To bychom museli jít a nakoupit jídlo pro všechny ty lidi.“"],[14,"Bylo tam totiž asi pět tisíc mužů. Ježíš řekl učedníkům: „Usaďte je do skupin asi po padesáti.“"],[15,"Učedníci to udělali a všichni se posadili."],[16,"Ježíš vzal pět chlebů a dvě ryby, vzhlédl k nebi, požehnal je, lámal a dával učedníkům, aby je rozdávali zástupu."],[17,"Všichni se najedli dosyta. Z toho, co zbylo, pak učedníci nasbírali dvanáct košů."]]},{"title":"Petrovo vyznání","range":"Lk 9,18–21","thoughts":[],"verses":[[18,"Jednou se Ježíš modlil o samotě a učedníci byli s ním. Zeptal se jich: „Za koho mě považují zástupy?“"],[19,"Odpověděli: „Za Jana Křtitele. Jiní za Eliáše a další říkají, že vstal některý ze starých proroků.“"],[20,"Zeptal se jich: „A za koho mě považujete vy?“ Petr odpověděl: „Za Božího Mesiáše.“"],[21,"Ježíš je důrazně varoval a přikázal jim, aby to nikomu neříkali."]]},{"title":"První předpověď utrpení","range":"Lk 9,22–27","thoughts":[],"verses":[[22,"Řekl: „Syn člověka musí mnoho trpět. Starší, velekněží a učitelé Zákona ho odmítnou, bude zabit a třetího dne vstane z mrtvých.“"],[23,"Potom řekl všem: „Kdo chce jít za mnou, ať zapře sám sebe, každý den vezme svůj kříž a následuje mě."],[24,"Kdo si totiž bude chtít zachránit život, ztratí ho. Kdo však svůj život ztratí kvůli mně, zachrání ho."],[25,"Co člověku prospěje, když získá celý svět, ale sám sebe ztratí nebo zničí?"],[26,"Kdo se bude stydět za mě a za má slova, za toho se bude stydět Syn člověka, až přijde ve své slávě, ve slávě Otce a svatých andělů."],[27,"Říkám vám pravdu: Někteří z těch, kdo tu stojí, nezemřou, dokud neuvidí Boží království.“"]]},{"title":"Proměnění na hoře","range":"Lk 9,28–36","thoughts":[],"verses":[[28,"Asi osm dní po těchto slovech vzal Ježíš Petra, Jana a Jakuba a vystoupil s nimi na horu, aby se modlil."],[29,"Když se modlil, vzhled jeho tváře se změnil a jeho oděv se rozzářil oslnivou bělostí."],[30,"Vtom s ním mluvili dva muži: Mojžíš a Eliáš."],[31,"Objevili se ve slávě a mluvili o Ježíšově odchodu, který se měl naplnit v Jeruzalémě."],[32,"Petr a jeho společníci byli přemoženi spánkem. Když se úplně probrali, uviděli Ježíšovu slávu a dva muže, kteří s ním stáli."],[33,"Když od něj ti muži odcházeli, Petr řekl Ježíšovi: „Mistře, je dobře, že jsme tady. Postavme tři přístřešky: jeden pro tebe, jeden pro Mojžíše a jeden pro Eliáše.“ Nevěděl, co říká."],[34,"Ještě když mluvil, objevil se oblak a zahalil je. Když vstupovali do oblaku, učedníci dostali strach."],[35,"Z oblaku zazněl hlas: „Toto je můj Syn, kterého jsem vyvolil. Toho poslouchejte.“"],[36,"Když hlas dozněl, zůstal tam Ježíš sám. Učedníci o tom tehdy mlčeli a nikomu nevyprávěli, co viděli."]]},{"title":"Uzdravení posedlého chlapce","range":"Lk 9,37–43","thoughts":[],"verses":[[37,"Když druhý den sestoupili z hory, přišel Ježíšovi naproti velký zástup."],[38,"Z davu vykřikl jeden muž: „Mistře, prosím tě, podívej se na mého syna. Je to moje jediné dítě."],[39,"Zmocňuje se ho zlý duch. Chlapec náhle vykřikne, duch jím zmítá, až má pěnu u úst, a jen těžko ho opouští. Úplně ho vyčerpává."],[40,"Prosil jsem tvé učedníky, aby ho vyhnali, ale nedokázali to.“"],[41,"Ježíš odpověděl: „Nevěřící a zvrácená generace! Jak dlouho ještě budu s vámi a budu vás snášet? Přiveď sem svého syna.“"],[42,"Ještě když chlapec přicházel, zlý duch ho srazil na zem a začal jím zmítat. Ježíš nečistému duchu přikázal, chlapce uzdravil a vrátil ho jeho otci."],[43,"Všichni žasli nad velikostí Boží moci. Když se všichni divili tomu, co Ježíš dělal, řekl svým učedníkům:"]]},{"title":"Druhá předpověď utrpení","range":"Lk 9,44–45","thoughts":[],"verses":[[44,"„Dobře si zapamatujte tato slova: Syn člověka bude vydán do rukou lidí.“"],[45,"Učedníci však těm slovům nerozuměli. Jejich význam jim zůstával skrytý, takže ho nechápali, a báli se Ježíše zeptat, co tím myslel."]]},{"title":"Kdo je největší","range":"Lk 9,46–50","thoughts":[],"verses":[[46,"Mezi učedníky vznikla hádka o to, kdo z nich je největší."],[47,"Ježíš znal myšlenky jejich srdcí, a tak vzal dítě a postavil je vedle sebe."],[48,"Řekl jim: „Kdo přijme toto dítě v mém jménu, přijímá mě. A kdo přijímá mě, přijímá toho, který mě poslal. Kdo je mezi vámi všemi nejmenší, ten je skutečně veliký.“"],[49,"Jan mu řekl: „Mistře, viděli jsme někoho, jak ve tvém jménu vyhání zlé duchy, a snažili jsme se mu v tom zabránit, protože nechodí s námi.“"],[50,"Ježíš mu odpověděl: „Nebraňte mu. Kdo není proti vám, je s vámi.“"]]},{"title":"Cesta do Jeruzaléma","range":"Lk 9,51–56","thoughts":[],"verses":[[51,"Když se blížil čas, kdy měl být Ježíš vzat vzhůru, pevně se rozhodl vydat do Jeruzaléma."],[52,"Poslal před sebou posly. Ti cestou vstoupili do jedné samařské vesnice, aby pro něj připravili nocleh."],[53,"Místní ho však nepřijali, protože bylo zřejmé, že míří do Jeruzaléma."],[54,"Když to viděli učedníci Jakub a Jan, řekli: „Pane, chceš, abychom přikázali ohni sestoupit z nebe a zničit je?“"],[55,"Ježíš se k nim obrátil a napomenul je."],[56,"Potom odešli do jiné vesnice."]]},{"title":"Následování Ježíše","range":"Lk 9,57–62","thoughts":[],"verses":[[57,"Když pokračovali v cestě, někdo Ježíšovi řekl: „Půjdu za tebou, kamkoli půjdeš.“"],[58,"Ježíš mu odpověděl: „Lišky mají doupata a ptáci hnízda, ale Syn člověka nemá, kde by složil hlavu.“"],[59,"Jinému řekl: „Pojď za mnou.“ Ten odpověděl: „Pane, dovol mi nejprve odejít a pohřbít svého otce.“"],[60,"Ježíš mu řekl: „Nech mrtvé, ať pohřbívají své mrtvé. Ty jdi a hlásej Boží království.“"],[61,"Jiný řekl: „Půjdu za tebou, Pane, ale dovol mi nejprve rozloučit se s rodinou.“"],[62,"Ježíš mu odpověděl: „Kdo položí ruku na pluh a potom se ohlíží zpět, není připravený pro Boží království.“"]]}];

LUKE_SECTIONS["10"] = [{"title":"Vyslání sedmdesáti","range":"Lk 10,1–16","thoughts":[],"verses":[[1,"Potom Pán vybral ještě dalších sedmdesát učedníků a poslal je po dvou před sebou do každého města a na každé místo, kam se sám chystal přijít."],[2,"Řekl jim: „Úroda je veliká, ale dělníků je málo. Proste proto Pána úrody, aby poslal dělníky na svou žeň."],[3,"Jděte. Posílám vás jako jehňata mezi vlky."],[4,"Neberte si měšec, brašnu ani náhradní obuv a cestou se nezdržujte dlouhými pozdravy."],[5,"Když vejdete do nějakého domu, nejprve řekněte: ‚Pokoj tomuto domu.‘"],[6,"Bude-li tam člověk, který pokoj přijímá, váš pokoj na něm spočine. Jestli ne, vrátí se k vám."],[7,"V tom domě zůstaňte a jezte a pijte, co vám dají. Dělník si totiž zaslouží svou mzdu. Nepřecházejte z domu do domu."],[8,"Když přijdete do některého města a přijmou vás, jezte, co vám nabídnou."],[9,"Uzdravujte tam nemocné a říkejte jim: ‚Boží království se k vám přiblížilo.‘"],[10,"Když však přijdete do města a nepřijmou vás, vyjděte do jeho ulic a řekněte:"],[11,"‚Setřásáme proti vám i prach z vašeho města, který nám ulpěl na nohou. Ale vězte: Boží království se přiblížilo.‘"],[12,"Říkám vám, že v den soudu na tom bude Sodoma lépe než takové město."],[13,"Běda ti, Chorazine! Běda ti, Betsaido! Kdyby se zázraky, které se staly u vás, staly v Týru a Sidónu, jejich obyvatelé by už dávno seděli v kajícím rouchu a popelu a činili pokání."],[14,"Proto na tom budou Týr a Sidón při soudu lépe než vy."],[15,"A ty, Kafarnaum, myslíš, že budeš vyvýšeno až do nebe? Budeš sraženo až do říše mrtvých."],[16,"Kdo poslouchá vás, poslouchá mě. Kdo odmítá vás, odmítá mě. A kdo odmítá mě, odmítá toho, který mě poslal.“"]]},{"title":"Návrat učedníků","range":"Lk 10,17–24","thoughts":[],"verses":[[17,"Těch sedmdesát se vrátilo s radostí a říkali: „Pane, ve tvém jménu se nám podřizují dokonce i zlí duchové.“"],[18,"Ježíš jim řekl: „Viděl jsem satana padat z nebe jako blesk."],[19,"Dal jsem vám moc šlapat po hadech a štírech a čelit veškeré síle nepřítele. Nic vám neublíží."],[20,"Neradujte se však z toho, že se vám podřizují duchové. Radujte se především z toho, že jsou vaše jména zapsána v nebi.“"],[21,"V té chvíli se Ježíš naplnil radostí v Duchu svatém a řekl: „Chválím tě, Otče, Pane nebe i země. Skryl jsi tyto věci před moudrými a chytrými a odhalil jsi je maličkým. Ano, Otče, tak se ti to zalíbilo."],[22,"Můj Otec mi všechno svěřil. Nikdo neví, kdo je Syn, kromě Otce, a nikdo neví, kdo je Otec, kromě Syna a toho, komu ho Syn chce dát poznat.“"],[23,"Potom se obrátil zvlášť k učedníkům a řekl: „Blaze očím, které vidí to, co vidíte vy."],[24,"Říkám vám, že mnoho proroků a králů toužilo vidět to, co vidíte vy, ale neviděli to, a slyšet to, co slyšíte vy, ale neslyšeli.“"]]},{"title":"Milosrdný Samařan","range":"Lk 10,25–37","thoughts":[],"verses":[[25,"Tu vstal jeden učitel Zákona a chtěl Ježíše vyzkoušet. Zeptal se: „Mistře, co mám dělat, abych získal věčný život?“"],[26,"Ježíš mu odpověděl: „Co je napsáno v Zákoně? Jak to tam čteš?“"],[27,"Odpověděl: „Miluj Pána, svého Boha, celým svým srdcem, celou svou duší, celou svou silou a celou svou myslí a svého bližního jako sám sebe.“"],[28,"Ježíš mu řekl: „Odpověděl jsi správně. Tak jednej a budeš žít.“"],[29,"On však chtěl ukázat, že jedná správně, a zeptal se Ježíše: „A kdo je vlastně můj bližní?“"],[30,"Ježíš odpověděl: „Jeden člověk šel z Jeruzaléma do Jericha a přepadli ho lupiči. Obrali ho, zbili a odešli. Nechali ho tam polomrtvého."],[31,"Náhodou šel tou cestou jeden kněz. Když ho uviděl, vyhnul se mu a pokračoval dál."],[32,"Stejně se zachoval i levita. Když přišel k tomu místu a uviděl ho, obešel ho."],[33,"Pak tudy cestoval jeden Samařan. Když k tomu člověku přišel a uviděl ho, bylo mu ho hluboce líto."],[34,"Přistoupil k němu, nalil mu na rány olej a víno a ovázal je. Potom ho posadil na své zvíře, odvezl do hostince a postaral se o něj."],[35,"Druhý den vytáhl dva denáry, dal je hostinskému a řekl: ‚Postarej se o něj. Jestli utratíš něco navíc, zaplatím ti to, až se budu vracet.‘"],[36,"Který z těch tří se podle tebe zachoval jako bližní k člověku, kterého přepadli lupiči?“"],[37,"Odpověděl: „Ten, který mu prokázal milosrdenství.“ Ježíš mu řekl: „Jdi a jednej stejně.“"]]},{"title":"Marie a Marta","range":"Lk 10,38–42","thoughts":[],"verses":[[38,"Když pokračovali v cestě, Ježíš přišel do jedné vesnice. Žena jménem Marta ho přijala do svého domu."],[39,"Měla sestru Marii. Ta si sedla k Pánovým nohám a poslouchala, co říká."],[40,"Marta však byla úplně zaměstnaná přípravami a obsluhováním. Přišla k Ježíšovi a řekla: „Pane, nevadí ti, že mě moje sestra nechala všechnu práci dělat samotnou? Řekni jí, ať mi pomůže.“"],[41,"Pán jí odpověděl: „Marto, Marto, děláš si starosti a znepokojuješ se kvůli mnoha věcem."],[42,"Potřebné je však jen jedno. Marie si vybrala to dobré a nikdo jí to nevezme.“"]]}];

LUKE_SECTIONS["11"] = [{"title":"Modlitba Páně","range":"Lk 11,1–4","thoughts":[],"verses":[[1,"Jednou se Ježíš na určitém místě modlil. Když skončil, jeden z jeho učedníků mu řekl: „Pane, nauč nás modlit se, jako Jan naučil své učedníky.“"],[2,"Ježíš jim řekl: „Když se modlíte, říkejte: Otče náš v nebi, ať je tvé jméno svaté. Ať přijde tvé království. Ať se děje tvá vůle na zemi stejně jako v nebi."],[3,"Dávej nám každý den chléb, který potřebujeme."],[4,"Odpusť nám naše hříchy, protože i my odpouštíme každému, kdo se provinil proti nám. Neuveď nás do pokušení, ale vysvoboď nás od zlého.“"]]},{"title":"Vytrvalost v modlitbě","range":"Lk 11,5–13","thoughts":[],"verses":[[5,"Potom jim řekl: „Představte si, že někdo z vás má přítele a přijde k němu o půlnoci: ‚Příteli, půjč mi tři chleby."],[6,"Právě ke mně dorazil přítel z cesty a nemám mu co nabídnout.‘"],[7,"Ten druhý mu zevnitř odpoví: ‚Neobtěžuj mě. Dveře už jsou zamčené a děti jsou se mnou v posteli. Nemohu teď vstát a něco ti dát.‘"],[8,"Říkám vám: I kdyby nevstal a nic mu nedal jen proto, že je to jeho přítel, kvůli jeho neodbytnosti nakonec vstane a dá mu všechno, co potřebuje."],[9,"Proto vám říkám: Proste a dostanete. Hledejte a najdete. Klepejte a bude vám otevřeno."],[10,"Protože každý, kdo prosí, dostává, kdo hledá, nachází, a tomu, kdo klepe, bude otevřeno."],[11,"Je mezi vámi takový otec, který by synovi podal kámen, když ho prosí o chléb? Nebo hada, když ho prosí o rybu?"],[12,"Nebo by mu dal štíra, když prosí o vejce?"],[13,"Jestliže tedy vy, přestože jste hříšní, umíte dávat svým dětem dobré dary, tím spíš dá váš nebeský Otec Ducha svatého těm, kdo ho prosí.“"]]},{"title":"Ježíš a Belzebul","range":"Lk 11,14–26","thoughts":[],"verses":[[14,"Ježíš jednou vyháněl zlého ducha, kvůli kterému člověk nemohl mluvit. Když duch vyšel, němý začal mluvit a zástupy žasly."],[15,"Někteří z nich však říkali: „Zlé duchy vyhání pomocí Belzebula, vládce zlých duchů.“"],[16,"Jiní ho chtěli vyzkoušet a žádali po něm znamení z nebe."],[17,"Ježíš však znal jejich myšlenky a řekl jim: „Každé království, které je rozdělené samo proti sobě, zpustne, a dům rozdělený proti sobě se zhroutí."],[18,"Jestliže je tedy satan rozdělen sám proti sobě, jak může jeho království obstát? Tvrdíte přece, že vyháním zlé duchy pomocí Belzebula."],[19,"Jestliže je já vyháním pomocí Belzebula, čí mocí je vyhánějí vaši lidé? Právě oni proto budou vašimi soudci."],[20,"Jestliže však vyháním zlé duchy Božím prstem, pak k vám skutečně přišlo Boží království."],[21,"Když silný a ozbrojený muž hlídá svůj dům, jeho majetek je v bezpečí."],[22,"Když však přijde někdo silnější, přemůže ho, vezme mu zbraně, na které spoléhal, a rozdělí jeho kořist."],[23,"Kdo není se mnou, je proti mně. A kdo se mnou neshromažďuje, rozptyluje."],[24,"Když nečistý duch vyjde z člověka, prochází vyprahlými místy a hledá odpočinek. Když ho nenajde, řekne si: ‚Vrátím se do svého domu, ze kterého jsem vyšel.‘"],[25,"Když se vrátí, najde ho vymetený a uklizený."],[26,"Potom jde a přivede s sebou sedm jiných duchů, horších, než je sám. Vejdou dovnitř a usadí se tam. Nakonec je na tom ten člověk hůř než na začátku.“"]]},{"title":"Pravé blahoslavenství","range":"Lk 11,27–28","thoughts":[],"verses":[[27,"Když to Ježíš říkal, jedna žena ze zástupu na něj zavolala: „Blaze ženě, která tě nosila v těle a kojila tě!“"],[28,"Ježíš však odpověděl: „Ano, ale ještě více blaze těm, kdo slyší Boží slovo a řídí se jím.“"]]},{"title":"Znamení Jonášovo","range":"Lk 11,29–32","thoughts":[],"verses":[[29,"Když se kolem něj shromažďovaly další zástupy, Ježíš začal říkat: „Tato generace je zlá. Chce znamení, ale žádné jiné znamení nedostane než znamení proroka Jonáše."],[30,"Jako se Jonáš stal znamením pro obyvatele Ninive, tak bude Syn člověka znamením pro tuto generaci."],[31,"Královna z jihu povstane při soudu spolu s lidmi této generace a odsoudí je. Přicestovala totiž z konce světa, aby slyšela Šalomounovu moudrost, a tady je někdo větší než Šalomoun."],[32,"Obyvatelé Ninive povstanou při soudu spolu s touto generací a odsoudí ji. Oni se totiž po Jonášově kázání obrátili, a tady je někdo větší než Jonáš."]]},{"title":"Lampa těla","range":"Lk 11,33–36","thoughts":[],"verses":[[33,"„Nikdo nerozsvítí lampu a potom ji neschová ani nepřikryje nádobou. Postaví ji na stojan, aby ti, kdo přicházejí dovnitř, viděli světlo."],[34,"Lampou těla je oko. Když je tvé oko zdravé, celé tvé tělo je plné světla. Když je však tvé oko špatné, je i tvé tělo plné tmy."],[35,"Dávej tedy pozor, aby světlo, které je v tobě, nebylo ve skutečnosti tmou."],[36,"Jestliže je celé tvé tělo plné světla a není v něm žádná temná část, bude celé zářit, jako když tě lampa osvítí svým světlem.“"]]},{"title":"Běda farizeům a zákoníkům","range":"Lk 11,37–54","thoughts":[],"verses":[[37,"Když Ježíš domluvil, jeden farizeus ho pozval k sobě na jídlo. Ježíš vešel a posadil se ke stolu."],[38,"Farizeus se podivil, že se Ježíš před jídlem nejprve obřadně neumyl."],[39,"Pán mu řekl: „Vy farizeové čistíte vnější stranu poháru a mísy, ale vaše nitro je plné chamtivosti a zla."],[40,"Pošetilci! Copak ten, kdo vytvořil vnějšek, nevytvořil také vnitřek?"],[41,"Dejte raději to, co máte, jako almužnu potřebným, a pak pro vás bude všechno čisté."],[42,"Ale běda vám, farizeové! Dáváte desátek z máty, routy a každé byliny, ale zanedbáváte spravedlnost a lásku k Bohu. Právě o tyto věci máte usilovat a přitom nezanedbávat ani ostatní."],[43,"Běda vám, farizeové! Milujete přední místa v synagogách a chcete, aby vás lidé zdravili na tržištích."],[44,"Běda vám! Jste jako neoznačené hroby, po kterých lidé chodí, aniž vědí, co je pod nimi.“"],[45,"Jeden z učitelů Zákona mu řekl: „Mistře, tím, co říkáš, urážíš i nás.“"],[46,"Ježíš odpověděl: „Běda i vám, učitelé Zákona! Nakládáte na lidi břemena, která se nedají unést, ale sami se těch břemen nedotknete ani jediným prstem."],[47,"Běda vám! Stavíte hrobky prorokům, které vaši předkové zabili."],[48,"Tím dosvědčujete, že souhlasíte s tím, co vaši předkové udělali: oni proroky zabili a vy jim stavíte hrobky."],[49,"Proto také Boží moudrost řekla: ‚Pošlu k nim proroky a apoštoly. Některé z nich zabijí a jiné budou pronásledovat.‘"],[50,"Tak bude tato generace volána k odpovědnosti za krev všech proroků, která byla prolita od založení světa,"],[51,"od krve Ábela až po krev Zachariáše, který zahynul mezi oltářem a chrámem. Ano, říkám vám, tato generace za ni ponese odpovědnost."],[52,"Běda vám, učitelé Zákona! Vzali jste klíč k poznání. Sami jste nevešli a těm, kdo chtěli vejít, jste v tom zabránili.“"],[53,"Když odtud Ježíš odešel, učitelé Zákona a farizeové na něj začali tvrdě dorážet a zahrnovali ho otázkami o mnoha věcech."],[54,"Číhali na něj a snažili se zachytit něco z jeho slov, aby ho mohli obžalovat."]]}];

LUKE_SECTIONS["12"] = [{"title":"Varování před pokrytectvím","range":"Lk 12,1–12","thoughts":[],"verses":[[1,"Mezitím se shromáždily tisíce lidí, takže se navzájem tlačili. Ježíš začal mluvit nejprve ke svým učedníkům: „Dávejte si pozor na kvas farizeů, tedy na pokrytectví."],[2,"Není nic skrytého, co nebude odhaleno, ani nic tajného, co nebude poznáno."],[3,"Proto všechno, co jste řekli ve tmě, bude slyšet na světle, a co jste šeptali v soukromí, bude hlásáno ze střech."],[4,"Vám, svým přátelům, říkám: Nebojte se těch, kdo mohou zabít tělo a potom už nemohou udělat nic víc."],[5,"Ukážu vám, koho se máte bát: toho, který má po zabití moc uvrhnout do pekelného ohně. Ano, říkám vám, toho se bojte."],[6,"Copak se pět vrabců neprodává za dvě drobné mince? A přesto Bůh nezapomíná ani na jednoho z nich."],[7,"Dokonce i všechny vlasy na vaší hlavě jsou spočítané. Nebojte se. Máte větší cenu než mnoho vrabců."],[8,"Říkám vám: Ke každému, kdo se ke mně přizná před lidmi, se také Syn člověka přizná před Božími anděly."],[9,"Kdo mě však před lidmi zapře, bude zapřen před Božími anděly."],[10,"Každému, kdo řekne něco proti Synu člověka, může být odpuštěno. Kdo se však rouhá Duchu svatému, tomu odpuštěno nebude."],[11,"Když vás budou přivádět do synagog a před vládce a úřady, nedělejte si starosti, jak se budete hájit nebo co máte říct."],[12,"Duch svatý vás totiž v té chvíli naučí, co máte říct.“"]]},{"title":"Podobenství o bohatém bláznu","range":"Lk 12,13–21","thoughts":[],"verses":[[13,"Někdo ze zástupu Ježíšovi řekl: „Mistře, řekni mému bratrovi, ať se se mnou rozdělí o dědictví.“"],[14,"Ježíš mu odpověděl: „Člověče, kdo mě ustanovil vaším soudcem nebo rozhodčím?“"],[15,"Potom všem řekl: „Dávejte si pozor a chraňte se každé chamtivosti. Život člověka totiž nezávisí na množství jeho majetku.“"],[16,"Vyprávěl jim podobenství: „Jednomu bohatému člověku přinesla pole velikou úrodu."],[17,"Přemýšlel: ‚Co mám dělat? Nemám už kam uložit svou úrodu.‘"],[18,"Pak si řekl: ‚Udělám toto: Zbořím své stodoly, postavím větší a do nich uložím všechno obilí i ostatní majetek."],[19,"A řeknu si: Máš zásoby na mnoho let. Odpočívej, jez, pij a užívej si.‘"],[20,"Bůh mu však řekl: ‚Blázne! Ještě této noci budeš muset odevzdat svůj život. Komu potom připadne to, co sis nashromáždil?‘"],[21,"Tak dopadne člověk, který shromažďuje poklady pro sebe, ale není bohatý před Bohem.“"]]},{"title":"Nestarejte se úzkostlivě","range":"Lk 12,22–34","thoughts":[],"verses":[[22,"Potom řekl svým učedníkům: „Proto vám říkám: Nedělejte si úzkostné starosti o svůj život, co budete jíst, ani o své tělo, co si obléknete."],[23,"Život je přece víc než jídlo a tělo víc než oblečení."],[24,"Podívejte se na havrany. Nesejí ani nesklízejí, nemají sklady ani stodoly, a přesto je Bůh živí. O kolik větší cenu máte vy než ptáci!"],[25,"Kdo z vás může svými starostmi přidat ke své postavě jediný loket?"],[26,"Jestliže tedy nedokážete ani tak malou věc, proč si děláte starosti o ostatní?"],[27,"Podívejte se, jak rostou lilie. Nepracují ani nepředou, a přesto vám říkám, že ani Šalomoun v celé své slávě nebyl oblečen tak jako jedna z nich."],[28,"Jestliže Bůh tak obléká trávu, která je dnes na poli a zítra se hodí do pece, o kolik spíš se postará o vás, lidé malé víry!"],[29,"Neshánějte se tedy úzkostlivě po tom, co budete jíst a pít, a nenechte se tím znepokojovat."],[30,"Za těmito věcmi se honí lidé tohoto světa. Váš Otec přece ví, že je potřebujete."],[31,"Hledejte především jeho království a toto všechno vám bude přidáno."],[32,"Neboj se, malé stádo. Vašemu Otci se zalíbilo dát vám království."],[33,"Prodávejte svůj majetek a dávejte potřebným. Pořiďte si měšce, které se neopotřebují, a poklad v nebi, který se neztratí, kam se nedostane zloděj a kde ho nezničí mol."],[34,"Kde je totiž váš poklad, tam bude i vaše srdce."]]},{"title":"Buďte připraveni","range":"Lk 12,35–48","thoughts":[],"verses":[[35,"„Buďte připraveni k službě a mějte rozsvícené lampy."],[36,"Buďte jako lidé, kteří čekají, až se jejich pán vrátí ze svatby, aby mu mohli hned otevřít, jakmile přijde a zaklepe."],[37,"Blaze služebníkům, které pán při svém příchodu najde bdít. Amen, říkám vám: Sám se přepáše, posadí je ke stolu, přijde k nim a bude je obsluhovat."],[38,"Ať přijde uprostřed noci nebo až nad ránem, blaze jim, pokud je najde připravené."],[39,"Uvědomte si toto: Kdyby majitel domu věděl, kdy přijde zloděj, nedovolil by mu vloupat se do svého domu."],[40,"Také vy buďte připraveni, protože Syn člověka přijde ve chvíli, kdy ho nečekáte.“"],[41,"Petr se zeptal: „Pane, říkáš toto podobenství jen nám, nebo všem?“"],[42,"Pán odpověděl: „Kdo je tedy věrný a rozumný správce, kterého pán ustanoví nad svým služebnictvem, aby jim v pravý čas dával příděl jídla?"],[43,"Blaze služebníku, kterého jeho pán při návratu najde, jak takto jedná."],[44,"Opravdu vám říkám, že ho ustanoví správcem všeho svého majetku."],[45,"Kdyby si však ten služebník řekl: ‚Můj pán se dlouho nevrací,‘ a začal bít služebníky a služebnice, jíst, pít a opíjet se,"],[46,"jeho pán přijde v den, kdy ho nečeká, a v hodinu, kterou nezná. Tvrdě ho potrestá a dá mu úděl mezi nevěrnými."],[47,"Služebník, který znal vůli svého pána, ale nepřipravil se a nejednal podle ní, dostane mnoho ran."],[48,"Ten, kdo ji neznal a udělal něco, co zasluhuje trest, dostane ran méně. Od každého, komu bylo mnoho dáno, bude mnoho požadováno. A komu bylo mnoho svěřeno, od toho se bude žádat tím víc."]]},{"title":"Oheň a rozdělení","range":"Lk 12,49–53","thoughts":[],"verses":[[49,"„Přišel jsem přinést na zem oheň. Jak si přeji, aby už hořel!"],[50,"Musím však ještě projít křtem, a jak jsem sevřený, dokud se to nenaplní!"],[51,"Myslíte si, že jsem přišel přinést na zemi pokoj? Ne, říkám vám, ale rozdělení."],[52,"Od této chvíle bude v jednom domě pět lidí rozděleno: tři proti dvěma a dva proti třem."],[53,"Otec se postaví proti synovi a syn proti otci, matka proti dceři a dcera proti matce, tchyně proti snaše a snacha proti tchyni.“"]]},{"title":"Rozpoznávání času","range":"Lk 12,54–59","thoughts":[],"verses":[[54,"Ježíš řekl také zástupům: „Když vidíte, že od západu přichází mrak, hned říkáte: ‚Bude pršet,‘ a skutečně prší."],[55,"Když vane jižní vítr, říkáte: ‚Bude horko,‘ a je."],[56,"Pokrytci! Umíte posoudit vzhled země a oblohy. Jak to, že nedokážete rozpoznat význam této doby?"],[57,"Proč sami nedokážete posoudit, co je správné?"],[58,"Když jdeš se svým protivníkem k soudu, snaž se s ním ještě cestou dohodnout. Jinak tě odvede k soudci, soudce tě předá strážci a ten tě zavře do vězení."],[59,"Říkám ti: Nevyjdeš odtud, dokud nezaplatíš poslední minci.“"]]}];

LUKE_SECTIONS["13"] = [{"title":"Výzva k obrácení","range":"Lk 13,1–9","thoughts":[],"verses":[[1,"V té době přišli někteří lidé a vyprávěli Ježíšovi o Galilejcích, jejichž krev Pilát smísil s krví jejich obětí."],[2,"Ježíš jim odpověděl: „Myslíte si, že tito Galilejci byli větší hříšníci než ostatní Galilejci, protože takto trpěli?"],[3,"Ne, říkám vám. Jestliže však nebudete činit pokání, všichni podobně zahynete."],[4,"A co těch osmnáct lidí, na které spadla věž v Siloe a zabila je? Myslíte si, že měli větší vinu než všichni ostatní obyvatelé Jeruzaléma?"],[5,"Ne, říkám vám. Jestliže však nebudete činit pokání, všichni podobně zahynete.“"],[6,"Potom vyprávěl toto podobenství: „Jeden člověk měl na své vinici zasazený fíkovník. Přišel na něm hledat ovoce, ale žádné nenašel."],[7,"Řekl tedy vinaři: ‚Už tři roky sem chodím hledat na tomto fíkovníku ovoce a nic nenacházím. Pokácej ho. Proč má zbytečně vyčerpávat půdu?‘"],[8,"Vinař mu odpověděl: ‚Pane, nech ho ještě tento rok. Okopu ho a pohnojím."],[9,"Třeba příští rok ponese ovoce. Jestli ne, potom ho pokácíš.‘“"]]},{"title":"Uzdravení ženy v sobotu","range":"Lk 13,10–17","thoughts":[],"verses":[[10,"Jednou Ježíš v sobotu učil v synagoze."],[11,"Byla tam žena, kterou už osmnáct let trápil duch nemoci. Byla úplně shrbená a nedokázala se narovnat."],[12,"Když ji Ježíš uviděl, zavolal ji k sobě a řekl: „Ženo, jsi osvobozena od své nemoci.“"],[13,"Položil na ni ruce a ona se okamžitě narovnala a začala oslavovat Boha."],[14,"Představený synagogy se však zlobil, že Ježíš uzdravoval v sobotu, a řekl zástupu: „Je šest dní, kdy se má pracovat. V těch dnech tedy přicházejte, abyste byli uzdraveni, a ne v sobotu.“"],[15,"Pán mu odpověděl: „Pokrytci! Copak každý z vás v sobotu neodvazuje svého vola nebo osla od žlabu a nevede ho napít?"],[16,"A tato žena, Abrahamova dcera, kterou satan držel spoutanou osmnáct let, neměla být v sobotu z tohoto pouta osvobozena?“"],[17,"Když to řekl, všichni jeho odpůrci se zastyděli, zatímco celý zástup se radoval ze všech velikých věcí, které dělal."]]},{"title":"Hořčičné zrno a kvas","range":"Lk 13,18–21","thoughts":[],"verses":[[18,"Ježíš řekl: „Čemu se podobá Boží království? K čemu je přirovnám?"],[19,"Podobá se hořčičnému zrnu, které člověk vzal a zasadil ve své zahradě. Vyrostlo a stalo se stromem a v jeho větvích si udělali hnízda ptáci.“"],[20,"A znovu řekl: „K čemu přirovnám Boží království?"],[21,"Podobá se kvasu, který žena vmísila do tří měřic mouky, až prokvasilo celé těsto.“"]]},{"title":"Těsná brána","range":"Lk 13,22–30","thoughts":[],"verses":[[22,"Ježíš pokračoval v cestě do Jeruzaléma a procházel městy a vesnicemi, kde učil."],[23,"Někdo se ho zeptal: „Pane, bude zachráněno jen málo lidí?“ Ježíš jim odpověděl:"],[24,"„Usilujte o to, abyste vešli těsnou branou. Říkám vám, že mnozí se budou snažit vejít, ale nedokážou to."],[25,"Až hospodář vstane a zavře dveře, budete stát venku, klepat a volat: ‚Pane, otevři nám!‘ On vám však odpoví: ‚Nevím, odkud jste.‘"],[26,"Pak začnete říkat: ‚Vždyť jsme s tebou jedli a pili a učil jsi v našich ulicích.‘"],[27,"On vám však řekne: ‚Nevím, odkud jste. Odejděte ode mě všichni, kdo pácháte zlo.‘"],[28,"Tam bude pláč a skřípění zubů, až uvidíte Abrahama, Izáka, Jákoba a všechny proroky v Božím království, zatímco sami budete venku."],[29,"Lidé přijdou od východu i západu, od severu i jihu a usednou ke stolu v Božím království."],[30,"A tak jsou poslední, kteří budou první, a první, kteří budou poslední.“"]]},{"title":"Ježíšův nářek nad Jeruzalémem","range":"Lk 13,31–35","thoughts":[],"verses":[[31,"V tu chvíli k němu přišli někteří farizeové a řekli: „Odejdi odsud, protože Herodes tě chce zabít.“"],[32,"Ježíš jim odpověděl: „Jděte a řekněte té lišce: ‚Dnes a zítra vyháním zlé duchy a uzdravuji a třetího dne dokončím.‘"],[33,"Přesto musím dnes, zítra i pozítří pokračovat v cestě, protože není možné, aby prorok zahynul mimo Jeruzalém."],[34,"Jeruzaléme, Jeruzaléme, zabíjíš proroky a kamenuješ ty, kdo jsou k tobě posláni! Kolikrát jsem chtěl shromáždit tvé děti, jako slepice shromažďuje kuřata pod křídla, ale nechtěli jste."],[35,"Hle, váš dům vám zůstane opuštěný. Říkám vám: Neuvidíte mě, dokud neřeknete: ‚Požehnaný, který přichází ve jménu Páně.‘“"]]}];

LUKE_SECTIONS["14"] = [{"title":"Uzdravení v sobotu","range":"Lk 14,1–6","thoughts":[],"verses":[[1,"Jednou v sobotu přišel Ježíš na jídlo do domu jednoho z předních farizeů. Přítomní ho pozorně sledovali."],[2,"Před ním stál člověk, který trpěl otoky."],[3,"Ježíš se obrátil na učitele Zákona a farizeje a zeptal se: „Je dovoleno v sobotu uzdravovat, nebo ne?“"],[4,"Oni mlčeli. Ježíš tedy nemocného vzal, uzdravil ho a propustil."],[5,"Potom jim řekl: „Kdyby někomu z vás spadl osel nebo vůl do studny, nevytáhl by ho hned, i kdyby byla sobota?“"],[6,"Na to mu nedokázali odpovědět."]]},{"title":"Pokora při hostině","range":"Lk 14,7–14","thoughts":[],"verses":[[7,"Když si Ježíš všiml, jak si hosté vybírají přední místa, řekl jim podobenství:"],[8,"„Když tě někdo pozve na svatbu, nesedej si na nejčestnější místo. Mohl by být pozván někdo váženější než ty."],[9,"Hostitel, který pozval vás oba, by pak přišel a řekl ti: ‚Uvolni mu místo.‘ A ty bys musel s hanbou odejít na poslední místo."],[10,"Když jsi pozván, sedni si raději na poslední místo. Až přijde hostitel, může ti říct: ‚Příteli, pojď výš.‘ Pak se ti dostane cti před ostatními hosty."],[11,"Každý, kdo se povyšuje, bude ponížen, a kdo se ponižuje, bude povýšen.“"],[12,"Potom řekl i tomu, kdo ho pozval: „Když pořádáš oběd nebo večeři, nezvi jen své přátele, bratry, příbuzné a bohaté sousedy. Mohli by tě pozvat na oplátku a tím bys svou odměnu už dostal."],[13,"Když pořádáš hostinu, pozvi raději chudé, zmrzačené, chromé a slepé."],[14,"Budeš šťastný, protože ti nemají čím odplatit. Odměny se ti dostane při vzkříšení spravedlivých.“"]]},{"title":"Podobenství o velké hostině","range":"Lk 14,15–24","thoughts":[],"verses":[[15,"Když to uslyšel jeden z hostů u stolu, řekl Ježíšovi: „Blaze tomu, kdo bude jíst při hostině v Božím království.“"],[16,"Ježíš mu odpověděl: „Jeden člověk připravil velikou večeři a pozval mnoho hostů."],[17,"Když nastal čas večeře, poslal svého služebníka, aby pozvaným řekl: ‚Pojďte, všechno už je připraveno.‘"],[18,"Všichni se však začali jeden po druhém vymlouvat. První řekl: ‚Koupil jsem pole a musím se na ně jít podívat. Prosím, omluv mě.‘"],[19,"Druhý řekl: ‚Koupil jsem pět párů volů a jdu je vyzkoušet. Prosím, omluv mě.‘"],[20,"Další řekl: ‚Právě jsem se oženil, a proto nemohu přijít.‘"],[21,"Služebník se vrátil a všechno oznámil svému pánovi. Hospodář se rozzlobil a řekl mu: ‚Rychle vyjdi na náměstí a do ulic města a přiveď sem chudé, zmrzačené, slepé a chromé.‘"],[22,"Služebník pak řekl: ‚Pane, udělal jsem, co jsi přikázal, a stále je tu místo.‘"],[23,"Pán mu řekl: ‚Vyjdi tedy na cesty a k ohradám a naléhej na lidi, aby přišli, ať se můj dům naplní."],[24,"Říkám vám, že nikdo z těch původně pozvaných mou večeři neokusí.‘“"]]},{"title":"Cena následování","range":"Lk 14,25–35","thoughts":[],"verses":[[25,"S Ježíšem šly velké zástupy. Obrátil se k nim a řekl:"],[26,"„Kdo přichází ke mně a není připraven vzdát se kvůli mně i svého otce, matky, ženy, dětí, bratrů, sester, a dokonce i vlastního života, nemůže být mým učedníkem."],[27,"Kdo nenese svůj kříž a nejde za mnou, nemůže být mým učedníkem."],[28,"Když chce někdo z vás postavit věž, nejprve si přece sedne a spočítá náklady, aby zjistil, jestli má dost prostředků na její dokončení."],[29,"Jinak by mohl položit základy, ale stavbu nedokončit, a všichni, kdo by to viděli, by se mu začali posmívat:"],[30,"‚Tento člověk začal stavět, ale nedokázal to dokončit.‘"],[31,"Nebo když se král chystá do války proti jinému králi, nejprve si sedne a zváží, zda se s deseti tisíci vojáky může postavit tomu, kdo proti němu táhne s dvaceti tisíci."],[32,"Pokud ne, vyšle poselstvo, dokud je protivník ještě daleko, a požádá o podmínky míru."],[33,"Stejně tak nikdo z vás, kdo se nezřekne všeho, co vlastní, nemůže být mým učedníkem."],[34,"Sůl je dobrá. Jestliže však ztratí svou slanost, čím ji znovu osolíte?"],[35,"Nehodí se ani do půdy, ani do hnoje; vyhodí se. Kdo má uši k slyšení, ať poslouchá.“"]]}];

LUKE_SECTIONS["15"] = [{"title":"Ztracená ovce","range":"Lk 15,1–7","thoughts":[],"verses":[[1,"K Ježíšovi přicházeli všichni výběrčí daní a další lidé považovaní za hříšníky, aby ho poslouchali."],[2,"Farizeové a učitelé Zákona reptali: „Tenhle člověk přijímá hříšníky a dokonce s nimi jí.“"],[3,"Ježíš jim proto vyprávěl toto podobenství:"],[4,"„Kdyby někdo z vás měl sto ovcí a jednu z nich ztratil, nenechá těch devadesát devět na pustině a nepůjde za tou ztracenou, dokud ji nenajde?"],[5,"Když ji najde, s radostí si ji položí na ramena."],[6,"Po návratu domů svolá přátele a sousedy a řekne jim: ‚Radujte se se mnou, protože jsem našel svou ztracenou ovci.‘"],[7,"Říkám vám, že stejně bude v nebi větší radost nad jedním hříšníkem, který činí pokání, než nad devadesáti devíti spravedlivými, kteří obrácení nepotřebují."]]},{"title":"Ztracená mince","range":"Lk 15,8–10","thoughts":[],"verses":[[8,"„Nebo si představte ženu, která má deset stříbrných grošů a jednu ztratí. Copak nerozsvítí lampu, nevymete dům a nebude pečlivě hledat, dokud ji nenajde?"],[9,"Když ji najde, svolá přítelkyně a sousedky a řekne: ‚Radujte se se mnou, protože jsem našla groš, který jsem ztratila.‘"],[10,"Stejně tak, říkám vám, mají Boží andělé radost nad jedním hříšníkem, který činí pokání.“"]]},{"title":"Marnotratný syn","range":"Lk 15,11–32","thoughts":[],"verses":[[11,"Ježíš pokračoval: „Jeden člověk měl dva syny."],[12,"Mladší z nich řekl otci: ‚Otče, dej mi část majetku, která mi připadne.‘ Otec tedy rozdělil majetek mezi oba syny."],[13,"Za několik dní mladší syn všechno shromáždil, odešel do daleké země a tam svůj majetek promarnil prostopášným životem."],[14,"Když všechno utratil, postihl tu zemi veliký hlad a on začal trpět nouzí."],[15,"Šel tedy a nechal se najmout u jednoho obyvatele té země. Ten ho poslal na svá pole pást prasata."],[16,"Toužil se nasytit alespoň lusky, které jedla prasata, ale nikdo mu nic nedal."],[17,"Tehdy se vzpamatoval a řekl si: ‚Kolik nádeníků mého otce má jídla víc než dost, a já tady umírám hlady!"],[18,"Vstanu, půjdu ke svému otci a řeknu mu: Otče, zhřešil jsem proti nebi i proti tobě."],[19,"Už si nezasloužím nazývat se tvým synem. Přijmi mě jako jednoho ze svých nádeníků.‘"],[20,"Vstal tedy a vydal se k otci. Když byl ještě daleko, otec ho uviděl, pohnul se soucitem, rozběhl se k němu, padl mu kolem krku a políbil ho."],[21,"Syn mu řekl: ‚Otče, zhřešil jsem proti nebi i proti tobě. Už si nezasloužím nazývat se tvým synem.‘"],[22,"Otec však řekl služebníkům: ‚Rychle přineste nejlepší šaty a oblečte ho. Dejte mu prsten na ruku a obuv na nohy."],[23,"Přiveďte vykrmené tele a zabijte je. Budeme jíst a slavit,"],[24,"protože tento můj syn byl mrtvý a znovu ožil, byl ztracený a našel se.‘ A začali slavit."],[25,"Starší syn byl mezitím na poli. Když se vracel a přiblížil se k domu, uslyšel zpěv a hluk oslavy."],[26,"Zavolal si jednoho ze služebníků a ptal se, co se děje."],[27,"Ten mu odpověděl: ‚Vrátil se tvůj bratr a tvůj otec nechal zabít vykrmené tele, protože se mu vrátil zdravý.‘"],[28,"Starší syn se rozzlobil a nechtěl jít dovnitř. Jeho otec tedy vyšel ven a prosil ho, aby šel dovnitř."],[29,"On však otci odpověděl: ‚Tolik let ti sloužím a nikdy jsem neporušil žádný tvůj příkaz. A přesto jsi mi nikdy nedal ani kůzle, abych mohl slavit se svými přáteli."],[30,"Ale když se vrátil tenhle tvůj syn, který prohýřil tvůj majetek s prostitutkami, nechal jsi pro něj zabít vykrmené tele!‘"],[31,"Otec mu řekl: ‚Synu, ty jsi stále se mnou a všechno, co mám, je tvoje."],[32,"Ale teď jsme museli slavit a radovat se, protože tento tvůj bratr byl mrtvý a znovu ožil, byl ztracený a našel se.‘“"]]}];

LUKE_SECTIONS["16"] = [{"title":"Podobenství o nepoctivém správci","range":"Lk 16,1–13","thoughts":[],"verses":[[1,"Ježíš řekl také svým učedníkům: „Jeden bohatý člověk měl správce, kterého obvinili, že rozhazuje jeho majetek."],[2,"Zavolal si ho a řekl: ‚Co to o tobě slyším? Předlož mi účty ze svého správcovství, protože už dál nemůžeš být správcem.‘"],[3,"Správce si řekl: ‚Co teď udělám, když mě pán zbavuje správcovství? Kopat nemám sílu a žebrat se stydím."],[4,"Už vím, co udělám, aby mě lidé přijali do svých domů, až o správcovství přijdu.‘"],[5,"Postupně si zavolal všechny dlužníky svého pána. Prvního se zeptal: ‚Kolik dlužíš mému pánovi?‘"],[6,"Odpověděl: ‚Sto tun oleje.‘ Správce mu řekl: ‚Vezmi svůj účet, rychle si sedni a napiš padesát.‘"],[7,"Potom se zeptal druhého: ‚A ty dlužíš kolik?‘ Odpověděl: ‚Sto korců pšenice.‘ Řekl mu: ‚Vezmi svůj účet a napiš osmdesát.‘"],[8,"Pán toho nepoctivého správce pochválil, že jednal prozíravě. Lidé tohoto světa jsou totiž ve svých záležitostech prozíravější než lidé světla."],[9,"A já vám říkám: Získávejte si přátele pomocí nespravedlivého mamonu, aby vás, až pomine, přijali do věčných příbytků."],[10,"Kdo je věrný v maličkosti, je věrný i ve velké věci. A kdo je nepoctivý v maličkosti, je nepoctivý i ve velké."],[11,"Jestliže jste tedy nebyli věrní v nespravedlivém mamonu, kdo vám svěří to pravé?"],[12,"A jestliže jste nebyli věrní v tom, co patří někomu jinému, kdo vám dá to, co má být vaše?"],[13,"Žádný služebník nemůže sloužit dvěma pánům. Jednoho bude nenávidět a druhého milovat, jednoho se bude držet a druhým pohrdne. Nemůžete sloužit Bohu i bohatství.“"]]},{"title":"Zákon a Boží království","range":"Lk 16,14–18","thoughts":[],"verses":[[14,"To všechno slyšeli farizeové, kteří milovali peníze, a Ježíšovi se posmívali."],[15,"Řekl jim: „Vy se před lidmi vydáváte za spravedlivé, ale Bůh zná vaše srdce. To, co lidé vysoce oceňují, může být před Bohem odporné."],[16,"Zákon a Proroci platili až do Jana. Od té doby se hlásá dobrá zpráva o Božím království a každý se do něj usilovně tlačí."],[17,"Snáze pomine nebe a země, než aby ze Zákona přestala platit jediná čárka."],[18,"Každý, kdo propustí svou manželku a vezme si jinou, cizoloží. A kdo si vezme ženu propuštěnou manželem, také cizoloží."]]},{"title":"Boháč a Lazar","range":"Lk 16,19–31","thoughts":[],"verses":[[19,"„Byl jeden bohatý člověk, který se oblékal do šarlatu a jemného plátna a každý den si nádherně hodoval."],[20,"U jeho brány lehával chudák jménem Lazar, celý pokrytý vředy."],[21,"Toužil se nasytit alespoň tím, co padalo z boháčova stolu. Dokonce přicházeli psi a lízali mu vředy."],[22,"Chudák zemřel a andělé ho odnesli do Abrahamova lůna. Zemřel také boháč a byl pohřben."],[23,"V říši mrtvých, kde trpěl, pozvedl oči a v dálce uviděl Abrahama a Lazara v jeho lůně."],[24,"Zavolal: ‚Otče Abrahame, slituj se nade mnou a pošli Lazara, aby namočil koneček prstu ve vodě a ochladil mi jazyk, protože v tomto ohni trpím.‘"],[25,"Abraham mu odpověděl: ‚Synu, vzpomeň si, že za svého života jsi dostával dobré věci, zatímco Lazar zlé. Teď je on zde utěšován a ty trpíš."],[26,"Navíc je mezi námi a vámi veliká propast, takže nikdo nemůže přejít od nás k vám ani od vás k nám.‘"],[27,"Boháč řekl: ‚Prosím tě tedy, otče, pošli ho do domu mého otce."],[28,"Mám pět bratrů. Ať je varuje, aby také oni nepřišli na toto místo utrpení.‘"],[29,"Abraham mu odpověděl: ‚Mají Mojžíše a Proroky. Ať je poslouchají.‘"],[30,"On však řekl: ‚Ne, otče Abrahame. Kdyby k nim přišel někdo z mrtvých, činili by pokání.‘"],[31,"Abraham mu řekl: ‚Jestliže neposlouchají Mojžíše a Proroky, nenechají se přesvědčit, ani kdyby někdo vstal z mrtvých.‘“"]]}];

LUKE_SECTIONS["17"] = [{"title":"Pohoršení, odpuštění a víra","range":"Lk 17,1–10","thoughts":[],"verses":[[1,"Ježíš řekl svým učedníkům: „Není možné, aby nepřišla pohoršení. Běda však tomu, skrze koho přicházejí."],[2,"Pro takového člověka by bylo lépe, kdyby mu pověsili na krk mlýnský kámen a hodili ho do moře, než aby pohoršil jednoho z těchto maličkých."],[3,"Dávejte na sebe pozor. Když tvůj bratr zhřeší, napomeň ho, a když toho bude litovat, odpusť mu."],[4,"I kdyby proti tobě zhřešil sedmkrát za den a sedmkrát se k tobě vrátil se slovy: ‚Lituji toho,‘ odpusť mu.“"],[5,"Apoštolové řekli Pánu: „Přidej nám víry.“"],[6,"Pán odpověděl: „Kdybyste měli víru jako hořčičné zrno, mohli byste této moruši říct: ‚Vykořeň se a přesaď se do moře,‘ a poslechla by vás."],[7,"Představte si, že někdo z vás má služebníka, který oře nebo pase stádo. Řekne mu snad, když se vrátí z pole: ‚Pojď si hned sednout ke stolu‘?"],[8,"Neřekne mu spíš: ‚Připrav mi večeři, uprav se a obsluhuj mě, dokud se nenajím a nenapiji. Potom se najíš a napiješ ty‘?"],[9,"Děkuje snad služebníkovi za to, že udělal, co mu bylo nařízeno?"],[10,"Stejně tak i vy, když uděláte všechno, co vám bylo přikázáno, řekněte: ‚Jsme neužiteční služebníci. Udělali jsme jen to, co jsme byli povinni udělat.‘“"]]},{"title":"Uzdravení deseti malomocných","range":"Lk 17,11–19","thoughts":[],"verses":[[11,"Na cestě do Jeruzaléma procházel Ježíš krajem mezi Samařskem a Galileou."],[12,"Když vstupoval do jedné vesnice, setkalo se s ním deset mužů postižených malomocenstvím. Zůstali stát v dálce"],[13,"a hlasitě volali: „Ježíši, Mistře, slituj se nad námi!“"],[14,"Když je Ježíš uviděl, řekl jim: „Jděte a ukažte se kněžím.“ A zatímco šli, byli očištěni."],[15,"Jeden z nich, když uviděl, že je uzdravený, se vrátil a hlasitě oslavoval Boha."],[16,"Padl tváří k zemi k Ježíšovým nohám a děkoval mu. Byl to Samařan."],[17,"Ježíš se zeptal: „Nebylo jich očištěno deset? Kde je těch devět?"],[18,"Nikdo jiný se nevrátil, aby vzdal Bohu chválu, než tento cizinec?“"],[19,"Potom mu řekl: „Vstaň a jdi. Tvá víra tě uzdravila.“"]]},{"title":"Příchod Božího království","range":"Lk 17,20–37","thoughts":[],"verses":[[20,"Farizeové se Ježíše zeptali, kdy přijde Boží království. Odpověděl jim: „Boží království nepřichází tak, aby se dalo vypozorovat."],[21,"Nebude možné říct: ‚Je tady!‘ nebo ‚Je tam!‘ Vždyť Boží království je mezi vámi.“"],[22,"Potom řekl učedníkům: „Přijdou dny, kdy budete toužit spatřit alespoň jeden den Syna člověka, ale neuvidíte ho."],[23,"Lidé vám budou říkat: ‚Je tam!‘ nebo ‚Je tady!‘ Nechoďte tam a neběhejte za nimi."],[24,"Jako blesk zazáří od jednoho konce oblohy až k druhému, tak tomu bude se Synem člověka v jeho den."],[25,"Nejprve však musí mnoho trpět a tato generace ho zavrhne."],[26,"Jak tomu bylo za dnů Noema, tak tomu bude i za dnů Syna člověka."],[27,"Lidé jedli, pili, ženili se a vdávali až do dne, kdy Noe vstoupil do archy. Pak přišla potopa a všechny zahubila."],[28,"Stejně tomu bylo za dnů Lota. Lidé jedli a pili, kupovali a prodávali, sázeli a stavěli."],[29,"V den, kdy Lot vyšel ze Sodomy, však z nebe začal pršet oheň a síra a všechny zahubily."],[30,"Stejně tomu bude v den, kdy se zjeví Syn člověka."],[31,"Kdo bude v ten den na střeše a své věci bude mít v domě, ať pro ně nesestupuje. A kdo bude na poli, ať se nevrací zpět."],[32,"Vzpomeňte si na Lotovu ženu."],[33,"Kdo se bude snažit zachránit svůj život, ztratí ho. Kdo ho ztratí, zachová ho při životě."],[34,"Říkám vám: Té noci budou dva na jednom lůžku; jeden bude vzat a druhý ponechán."],[35,"Dvě ženy budou společně mlít; jedna bude vzata a druhá ponechána."],[36,"Dva budou na poli; jeden bude vzat a druhý ponechán."],[37,"Učedníci se ho zeptali: „Kde, Pane?“ Odpověděl jim: „Kde bude tělo, tam se shromáždí i orli.“"]]}];

LUKE_SECTIONS["18"] = [{"title":"Vytrvalá vdova","range":"Lk 18,1–8","thoughts":[],"verses":[[1,"Ježíš jim vyprávěl podobenství o tom, že je třeba stále se modlit a nevzdávat se."],[2,"Řekl: „V jednom městě žil soudce, který se nebál Boha a na lidi nebral ohled."],[3,"V tom městě žila také vdova. Stále k němu chodila a říkala: ‚Dopomoz mi ke spravedlnosti proti mému protivníkovi.‘"],[4,"Dlouho nechtěl. Nakonec si však řekl: ‚I když se Boha nebojím a na lidi neberu ohled,"],[5,"tahle vdova mi nedá pokoj. Dopomohu jí ke spravedlnosti, aby mě nakonec svým neustálým chozením neumořila.‘“"],[6,"Pán řekl: „Všimněte si, co říká ten nespravedlivý soudce."],[7,"A což teprve Bůh! Copak Bůh nedopomůže ke spravedlnosti svým vyvoleným, kteří k němu volají dnem i nocí, i když s nimi má trpělivost?"],[8,"Říkám vám, že jim ke spravedlnosti dopomůže brzy. Ale až přijde Syn člověka, najde na zemi víru?“"]]},{"title":"Farizeus a celník","range":"Lk 18,9–14","thoughts":[],"verses":[[9,"Některým lidem, kteří si byli jisti vlastní spravedlností a ostatními pohrdali, vyprávěl Ježíš toto podobenství:"],[10,"„Dva muži přišli do chrámu, aby se modlili. Jeden byl farizeus a druhý celník."],[11,"Farizeus se postavil a v duchu se modlil: ‚Bože, děkuji ti, že nejsem jako ostatní lidé: lupiči, nespravedliví, cizoložníci ani jako tento celník."],[12,"Postím se dvakrát týdně a dávám desátek ze všeho, co získám.‘"],[13,"Celník však stál opodál a neodvažoval se ani pozvednout oči k nebi. Bil se do prsou a říkal: ‚Bože, slituj se nade mnou, hříšníkem.‘"],[14,"Říkám vám, že tento člověk odešel domů ospravedlněný před Bohem, na rozdíl od toho druhého. Každý, kdo se povyšuje, bude ponížen, a kdo se ponižuje, bude povýšen.“"]]},{"title":"Ježíš a děti","range":"Lk 18,15–17","thoughts":[],"verses":[[15,"Lidé k Ježíšovi přinášeli i malé děti, aby se jich dotkl. Když to učedníci viděli, napomínali je."],[16,"Ježíš si však děti zavolal a řekl: „Nechte děti přicházet ke mně a nebraňte jim, protože takovým patří Boží království."],[17,"Amen, říkám vám: Kdo nepřijme Boží království jako dítě, vůbec do něj nevejde.“"]]},{"title":"Bohatý přední muž","range":"Lk 18,18–30","thoughts":[],"verses":[[18,"Jeden přední muž se Ježíše zeptal: „Dobrý Mistře, co mám dělat, abych získal věčný život?“"],[19,"Ježíš mu odpověděl: „Proč mě nazýváš dobrým? Nikdo není dobrý kromě jediného Boha."],[20,"Znáš přikázání: Necizolož, nezabíjej, nekraď, nevydávej křivé svědectví, cti svého otce a matku.“"],[21,"Muž řekl: „To všechno zachovávám od svého mládí.“"],[22,"Když to Ježíš uslyšel, řekl mu: „Ještě ti jedno schází. Prodej všechno, co máš, rozděl to chudým a budeš mít poklad v nebi. Potom přijď a následuj mě.“"],[23,"Když to muž uslyšel, velmi se zarmoutil, protože byl velice bohatý."],[24,"Ježíš viděl jeho smutek a řekl: „Jak těžko vcházejí do Božího království ti, kdo mají bohatství!"],[25,"Snáze projde velbloud uchem jehly, než bohatý člověk vejde do Božího království.“"],[26,"Ti, kdo to slyšeli, se zeptali: „Kdo tedy může být zachráněn?“"],[27,"Ježíš odpověděl: „Co je nemožné pro lidi, je možné pro Boha.“"],[28,"Petr řekl: „Podívej, my jsme opustili, co jsme měli, a šli jsme za tebou.“"],[29,"Ježíš jim řekl: „Amen, říkám vám: Není nikdo, kdo by kvůli Božímu království opustil dům, manželku, bratry, rodiče nebo děti,"],[30,"a nedostal už v tomto čase mnohonásobně víc a v budoucím věku věčný život.“"]]},{"title":"Třetí předpověď utrpení","range":"Lk 18,31–34","thoughts":[],"verses":[[31,"Ježíš si vzal Dvanáct stranou a řekl jim: „Teď jdeme do Jeruzaléma a naplní se všechno, co proroci napsali o Synu člověka."],[32,"Bude vydán pohanům, budou se mu posmívat, zneuctí ho a poplivou."],[33,"Zbičují ho a zabijí, ale třetího dne vstane z mrtvých.“"],[34,"Učedníci však ničemu z toho nerozuměli. Smysl těch slov jim zůstával skrytý a nechápali, o čem Ježíš mluví."]]},{"title":"Uzdravení slepého u Jericha","range":"Lk 18,35–43","thoughts":[],"verses":[[35,"Když se Ježíš blížil k Jerichu, seděl u cesty slepý muž a žebral."],[36,"Uslyšel procházet zástup a ptal se, co se děje."],[37,"Řekli mu, že tudy prochází Ježíš Nazaretský."],[38,"Muž začal volat: „Ježíši, Synu Davidův, slituj se nade mnou!“"],[39,"Lidé, kteří šli vpředu, ho napomínali, aby mlčel. On však volal ještě hlasitěji: „Synu Davidův, slituj se nade mnou!“"],[40,"Ježíš se zastavil a přikázal, aby muže přivedli k němu. Když se přiblížil, zeptal se ho:"],[41,"„Co chceš, abych pro tebe udělal?“ Odpověděl: „Pane, ať zase vidím.“"],[42,"Ježíš mu řekl: „Prohlédni. Tvá víra tě uzdravila.“"],[43,"Muž okamžitě prohlédl a šel za Ježíšem a oslavoval Boha. Když to všichni lidé viděli, také vzdávali Bohu chválu."]]}];

LUKE_SECTIONS["19"] = [{"title":"Zacheus","range":"Lk 19,1–10","thoughts":[],"verses":[[1,"Ježíš vešel do Jericha a procházel městem."],[2,"Žil tam muž jménem Zacheus. Byl představeným celníků a byl bohatý."],[3,"Chtěl vidět Ježíše a zjistit, kdo to je, ale kvůli zástupu nemohl, protože byl malé postavy."],[4,"Rozběhl se tedy napřed a vylezl na fíkovník, aby Ježíše uviděl, protože měl procházet právě tudy."],[5,"Když Ježíš přišel k tomu místu, podíval se vzhůru a řekl mu: „Zachee, rychle slez dolů. Dnes musím zůstat ve tvém domě.“"],[6,"Zacheus rychle slezl a s radostí ho přijal."],[7,"Když to lidé viděli, všichni reptali: „Vešel jako host k hříšnému člověku.“"],[8,"Zacheus se postavil a řekl Pánu: „Pane, polovinu svého majetku dávám chudým. A jestli jsem někoho o něco připravil, vrátím mu to čtyřnásobně.“"],[9,"Ježíš mu řekl: „Dnes přišla do tohoto domu spása, protože i tento člověk je Abrahamův syn."],[10,"Syn člověka totiž přišel hledat a spasit to, co bylo ztracené.“"]]},{"title":"Podobenství o hřivnách","range":"Lk 19,11–27","thoughts":[],"verses":[[11,"Když to lidé poslouchali, Ježíš přidal ještě jedno podobenství. Byl totiž blízko Jeruzaléma a oni si mysleli, že se Boží království projeví okamžitě."],[12,"Řekl: „Jeden muž vznešeného původu odcestoval do daleké země, aby tam přijal království a potom se vrátil."],[13,"Zavolal deset svých služebníků a dal jim deset hřiven a řekl jim: ‚Obchodujte s nimi, dokud se nevrátím.‘"],[14,"Jeho spoluobčané ho však nenáviděli a poslali za ním poselstvo se vzkazem: ‚Nechceme, aby tento člověk nad námi vládl.‘"],[15,"Když se po přijetí království vrátil, nechal si zavolat služebníky, kterým svěřil peníze, aby zjistil, kolik kdo vydělal."],[16,"Přišel první a řekl: ‚Pane, tvoje hřivna vydělala dalších deset.‘"],[17,"Pán mu odpověděl: ‚Výborně, dobrý služebníku. Protože jsi byl věrný v malé věci, budeš spravovat deset měst.‘"],[18,"Přišel druhý a řekl: ‚Pane, tvoje hřivna vydělala dalších pět.‘"],[19,"Tomu řekl: ‚Ty budeš spravovat pět měst.‘"],[20,"Pak přišel další a řekl: ‚Pane, tady je tvoje hřivna. Měl jsem ji schovanou v šátku,"],[21,"protože jsem se tě bál. Jsi přísný člověk: bereš, co jsi nevložil, a sklízíš, co jsi nezasel.‘"],[22,"Pán mu odpověděl: ‚Podle tvých vlastních slov tě soudím, špatný služebníku. Věděl jsi, že jsem přísný člověk, že beru, co jsem nevložil, a sklízím, co jsem nezasel."],[23,"Proč jsi tedy mé peníze nedal do banky? Po návratu bych je vybral i s úrokem.‘"],[24,"Potom řekl přítomným: ‚Vezměte mu tu hřivnu a dejte ji tomu, který má deset.‘"],[25,"Namítli: ‚Pane, vždyť už má deset hřiven!‘"],[26,"Odpověděl: ‚Říkám vám: Každému, kdo má, bude dáno. Kdo nemá, tomu bude vzato i to, co má."],[27,"A ty mé nepřátele, kteří nechtěli, abych nad nimi vládl, přiveďte sem a pobijte je přede mnou.‘“"]]},{"title":"Vjezd do Jeruzaléma","range":"Lk 19,28–40","thoughts":[],"verses":[[28,"Když to Ježíš řekl, pokračoval v cestě vzhůru do Jeruzaléma."],[29,"Když se přiblížil k Betfage a Betanii u hory zvané Olivová, poslal dva ze svých učedníků"],[30,"se slovy: „Jděte do vesnice před vámi. Jakmile do ní vstoupíte, najdete uvázané oslátko, na kterém ještě nikdo neseděl. Odvažte je a přiveďte."],[31,"Kdyby se vás někdo zeptal, proč je odvazujete, řekněte: ‚Pán je potřebuje.‘“"],[32,"Poslaní učedníci odešli a našli všechno tak, jak jim řekl."],[33,"Když oslátko odvazovali, jeho majitelé se jich zeptali: „Proč to oslátko odvazujete?“"],[34,"Odpověděli: „Pán je potřebuje.“"],[35,"Přivedli oslátko k Ježíšovi, položili na ně své pláště a posadili na ně Ježíše."],[36,"Když jel, lidé prostírali své pláště na cestu."],[37,"Když se přiblížil k místu, kde cesta sestupuje z Olivové hory, celý zástup učedníků začal s radostí a hlasitě chválit Boha za všechny mocné činy, které viděli."],[38,"Volali: „Požehnaný král, který přichází ve jménu Páně! Pokoj v nebi a sláva na výsostech!“"],[39,"Někteří farizeové ze zástupu mu řekli: „Mistře, napomeň své učedníky.“"],[40,"Ježíš odpověděl: „Říkám vám: Kdyby oni mlčeli, začalo by volat kamení.“"]]},{"title":"Ježíš pláče nad Jeruzalémem","range":"Lk 19,41–44","thoughts":[],"verses":[[41,"Když se Ježíš přiblížil k Jeruzalému a uviděl město, rozplakal se nad ním"],[42,"a řekl: „Kéž bys i ty právě dnes poznalo, co ti může přinést pokoj! Teď je to však skryté před tvýma očima."],[43,"Přijdou na tebe dny, kdy tvoji nepřátelé tě obklíčí valem, oblehnou tě a sevřou ze všech stran."],[44,"Srovnají se zemí tebe i tvé obyvatele a nenechají v tobě kámen na kameni, protože jsi nepoznalo čas svého navštívení.“"]]},{"title":"Vyčištění chrámu","range":"Lk 19,45–48","thoughts":[],"verses":[[45,"Potom Ježíš vešel do chrámu a začal z něj vyhánět prodavače i kupce."],[46,"Řekl jim: „Je napsáno: ‚Můj dům bude domem modlitby,‘ ale vy jste z něj udělali doupě lupičů.“"],[47,"Každý den pak učil v chrámu. Velekněží, učitelé Zákona a přední muži lidu hledali způsob, jak ho zabít."],[48,"Nevěděli však, jak to udělat, protože všechen lid ho se zaujetím poslouchal."]]}];

LUKE_SECTIONS["20"] = [{"title":"Otázka Ježíšovy autority","range":"Lk 20,1–8","thoughts":[],"verses":[[1,"Jednoho dne Ježíš učil lid v chrámu a kázal evangelium. Přišli k němu velekněží, učitelé Zákona a starší"],[2,"a zeptali se ho: „Řekni nám, jakou mocí tohle děláš a kdo ti tuto moc dal?“"],[3,"Ježíš jim odpověděl: „Také já se vás na něco zeptám. Řekněte mi:"],[4,"Pocházel Janův křest z nebe, nebo od lidí?“"],[5,"Začali se mezi sebou radit: „Když řekneme: ‚Z nebe,‘ zeptá se: ‚Proč jste mu tedy neuvěřili?‘"],[6,"Když ale řekneme: ‚Od lidí,‘ všechen lid nás ukamenuje, protože je přesvědčený, že Jan byl prorok.“"],[7,"Odpověděli tedy, že nevědí, odkud pocházel."],[8,"Ježíš jim řekl: „Ani já vám tedy neřeknu, jakou pravomocí tohle dělám.“"]]},{"title":"Podobenství o zlých vinařích","range":"Lk 20,9–19","thoughts":[],"verses":[[9,"Potom začal lidu vyprávět toto podobenství: „Jeden člověk vysadil vinici, pronajal ji vinařům a na dlouhou dobu odcestoval."],[10,"Když přišel čas sklizně, poslal k vinařům služebníka, aby mu dali jeho podíl z úrody. Vinaři ho však zbili a poslali zpět s prázdnou."],[11,"Poslal tedy jiného služebníka. Také toho zbili, ponížili a poslali zpět s prázdnou."],[12,"Poslal ještě třetího. Toho zranili a vyhodili ven."],[13,"Majitel vinice si řekl: ‚Co mám udělat? Pošlu svého milovaného syna. Snad se před ním zastydí.‘"],[14,"Když ho však vinaři uviděli, začali se mezi sebou domlouvat: ‚Tohle je dědic. Zabijme ho a dědictví bude naše.‘"],[15,"Vyhodili ho tedy z vinice a zabili. Co jim teď majitel vinice udělá?"],[16,"Přijde, ty vinaře zahubí a vinici dá jiným.“ Když to lidé uslyšeli, řekli: „Jen to ne!“"],[17,"Ježíš se na ně podíval a řekl: „Co tedy znamená to, co je napsáno: ‚Kámen, který stavitelé odmítli, se stal kamenem úhelným‘?"],[18,"Každý, kdo na ten kámen padne, se roztříští, a na koho padne on, toho rozdrtí na prach.“"],[19,"Učitelé Zákona a velekněží se ho chtěli v té chvíli zmocnit, protože pochopili, že toto podobenství řekl proti nim. Báli se však lidu."]]},{"title":"Daň císaři","range":"Lk 20,20–26","thoughts":[],"verses":[[20,"Začali tedy Ježíše sledovat a poslali k němu nastrčené lidi, kteří předstírali upřímnost. Chtěli ho chytit za slovo, aby ho mohli vydat vrchnosti a do moci místodržitele."],[21,"Zeptali se ho: „Mistře, víme, že mluvíš a učíš správně, nikomu nestraníš a pravdivě učíš Boží cestě."],[22,"Je nám dovoleno platit daň císaři, nebo ne?“"],[23,"Ježíš však prohlédl jejich lest a řekl: „Proč mě pokoušíte?"],[24,"Ukažte mi denár. Čí obraz a nápis na něm je?“ Odpověděli: „Císařův.“"],[25,"Ježíš jim řekl: „Dávejte tedy císaři, co patří císaři, a Bohu, co patří Bohu.“"],[26,"Před lidmi ho nedokázali chytit za slovo. Jeho odpověď je ohromila, a tak zmlkli."]]},{"title":"Otázka vzkříšení","range":"Lk 20,27–40","thoughts":[],"verses":[[27,"Potom k Ježíšovi přišli někteří saduceové, kteří tvrdí, že není vzkříšení, a položili mu otázku:"],[28,"„Mistře, Mojžíš nám napsal: Když někomu zemře ženatý bratr bez dětí, má si jeho bratr vzít vdovu a zachovat tak potomstvo svému bratrovi."],[29,"Bylo tedy sedm bratrů. První se oženil a zemřel bezdětný."],[30,"Ženu si potom vzal druhý"],[31,"a po něm třetí. Stejně to bylo se všemi sedmi; zemřeli a nezanechali děti."],[32,"Nakonec zemřela i ta žena."],[33,"Komu z nich tedy bude při vzkříšení manželkou? Vždyť ji mělo za manželku všech sedm.“"],[34,"Ježíš jim odpověděl: „Lidé tohoto věku se žení a vdávají."],[35,"Ti, kdo budou uznáni za hodné účasti na budoucím věku a vzkříšení z mrtvých, se však už ženit ani vdávat nebudou."],[36,"Už totiž nemohou zemřít, protože jsou rovni andělům. Jsou Božími dětmi, protože jsou dětmi vzkříšení."],[37,"A že mrtví vstávají, naznačil i Mojžíš v příběhu o hořícím keři, když nazývá Pána Bohem Abrahamovým, Bohem Izákovým a Bohem Jákobovým."],[38,"Bůh není Bohem mrtvých, ale živých, protože pro něj jsou všichni živí.“"],[39,"Někteří učitelé Zákona mu řekli: „Mistře, dobře jsi odpověděl.“"],[40,"A už se ho neodvažovali na nic dalšího ptát."]]},{"title":"Čí syn je Mesiáš","range":"Lk 20,41–44","thoughts":[],"verses":[[41,"Ježíš se jich zeptal: „Jak mohou říkat, že Mesiáš je Davidův syn?"],[42,"Vždyť sám David v knize Žalmů říká: ‚Pán řekl mému Pánu: Posaď se po mé pravici,"],[43,"dokud nepoložím tvé nepřátele pod tvé nohy.‘"],[44,"David ho tedy nazývá Pánem. Jak tedy může být jeho synem?“"]]},{"title":"Varování před zákoníky","range":"Lk 20,45–47","thoughts":[],"verses":[[45,"Před vším lidem Ježíš řekl svým učedníkům:"],[46,"„Dávejte si pozor na učitele Zákona. Rádi chodí v dlouhých oděvech, milují pozdravy na tržištích, přední sedadla v synagogách a čestná místa na hostinách."],[47,"Pohlcují majetek vdov a přitom se naoko dlouze modlí. Ty čeká tím přísnější soud.“"]]}];

LUKE_SECTIONS["21"] = [{"title":"Dar chudé vdovy","range":"Lk 21,1–4","thoughts":[],"verses":[[1,"Ježíš se rozhlédl a viděl bohaté lidi, jak dávají své dary do chrámové pokladnice."],[2,"Uviděl také chudou vdovu, která tam vhodila dvě drobné mince, dva šarty."],[3,"Řekl: „Opravdu vám říkám, že tato chudá vdova dala víc než všichni ostatní."],[4,"Oni totiž dávali Bohu dary z toho, co jim přebývalo. Ona však ze své chudoby dala všechno, z čeho měla žít.“"]]},{"title":"Proroctví o zničení chrámu","range":"Lk 21,5–9","thoughts":[],"verses":[[5,"Když někteří mluvili o tom, jak je chrám ozdoben krásnými kameny a zasvěcenými dary, Ježíš řekl:"],[6,"„Přijdou dny, kdy z toho, na co se díváte, nezůstane kámen na kameni. Všechno bude zbořeno.“"],[7,"Zeptali se ho: „Mistře, kdy se to stane? A jaké bude znamení, že se to má stát?“"],[8,"Ježíš odpověděl: „Dávejte si pozor, abyste se nenechali svést. Mnozí přijdou v mém jménu a budou říkat: ‚Já jsem to‘ a ‚Čas se přiblížil.‘ Nechoďte za nimi."],[9,"Až uslyšíte o válkách a nepokojích, neděste se. To všechno musí nejprve přijít, ale konec nenastane hned.“"]]},{"title":"Války a pronásledování","range":"Lk 21,10–19","thoughts":[],"verses":[[10,"Potom jim řekl: „Povstane národ proti národu a království proti království."],[11,"Na různých místech budou silná zemětřesení, hlad a epidemie. Budou přicházet hrůzy a veliká znamení z nebe."],[12,"Ještě před tím vším se vás však zmocní a budou vás pronásledovat. Budou vás vydávat do synagog a vězení a kvůli mému jménu vás povedou před krále a místodržitele."],[13,"To se vám stane příležitostí ke svědectví."],[14,"Rozhodněte se proto předem, že si nebudete připravovat svou obhajobu."],[15,"Já vám totiž dám ústa a moudrost, kterým žádný z vašich protivníků nebude schopen odporovat ani je vyvrátit."],[16,"Budou vás zrazovat dokonce rodiče, bratři, příbuzní a přátelé a některé z vás nechají zabít."],[17,"Kvůli mému jménu vás budou všichni nenávidět."],[18,"Ale ani vlas z vaší hlavy se neztratí."],[19,"Svou trpělivostí zachováte své životy."]]},{"title":"Zkáza Jeruzaléma","range":"Lk 21,20–24","thoughts":[],"verses":[[20,"„Až uvidíte Jeruzalém obklíčený vojsky, vězte, že se přiblížila jeho zkáza."],[21,"Tehdy ať ti, kdo jsou v Judsku, utečou do hor, ti, kdo jsou ve městě, ať z něj odejdou, a ti, kdo jsou na venkově, ať do něj nevstupují."],[22,"Budou to totiž dny odplaty, aby se naplnilo všechno, co je napsáno."],[23,"Běda těhotným a kojícím ženám v těch dnech! V této zemi bude veliká tíseň a na tento lid dopadne hněv."],[24,"Budou padat ostřím meče a budou odváděni do zajetí mezi všechny národy. Jeruzalém budou pošlapávat pohané, dokud se nenaplní čas pohanů."]]},{"title":"Příchod Syna člověka","range":"Lk 21,25–28","thoughts":[],"verses":[[25,"„Budou znamení na slunci, měsíci a hvězdách. Na zemi zachvátí národy úzkost a bezradnost kvůli hukotu moře a vlnobití."],[26,"Lidé budou umdlévat strachem a očekáváním toho, co přichází na svět, protože nebeské mocnosti se zachvějí."],[27,"Tehdy uvidí Syna člověka přicházet v oblaku s velikou mocí a slávou."],[28,"Až se to začne dít, vzhlédněte a zvedněte hlavy, protože se blíží vaše vykoupení.“"]]},{"title":"Podobenství o fíkovníku","range":"Lk 21,29–33","thoughts":[],"verses":[[29,"Potom jim vyprávěl podobenství: „Podívejte se na fíkovník a na všechny ostatní stromy."],[30,"Když vidíte, že raší, sami poznáváte, že léto už je blízko."],[31,"Stejně tak, až uvidíte, že se tyto věci dějí, vězte, že Boží království je blízko."],[32,"Amen, říkám vám: Tato generace nepomine, dokud se to všechno nestane."],[33,"Nebe a země pominou, ale má slova nikdy nepominou."]]},{"title":"Bděte","range":"Lk 21,34–38","thoughts":[],"verses":[[34,"„Dávejte si na sebe pozor, aby vaše srdce nebyla zatížena přejídáním, opilstvím a starostmi tohoto života a aby vás ten den náhle nezaskočil jako past."],[35,"Přijde totiž na všechny, kdo žijí po celé zemi."],[36,"Proto stále bděte a modlete se, abyste byli hodni uniknout všemu, co má přijít, a postavit se před Synem člověka.“"],[37,"Přes den Ježíš učil v chrámu a na noc odcházel na horu zvanou Olivová."],[38,"A všechen lid k němu časně ráno přicházel do chrámu, aby ho poslouchal."]]}];

LUKE_SECTIONS["22"] = [{"title":"Spiknutí a Jidášova zrada","range":"Lk 22,1–6","thoughts":[],"verses":[[1,"Blížil se svátek nekvašených chlebů, kterému se říká Velikonoce."],[2,"Velekněží a učitelé Zákona hledali způsob, jak Ježíše zabít, protože se báli lidu."],[3,"Tehdy vstoupil satan do Jidáše zvaného Iškariotský, jednoho z Dvanácti."],[4,"Jidáš odešel a domluvil se s velekněžími a veliteli chrámové stráže, jak jim Ježíše vydá."],[5,"Ti se zaradovali a dohodli se, že mu dají peníze."],[6,"Jidáš souhlasil a hledal vhodnou příležitost, kdy by jim Ježíše vydal stranou od zástupu."]]},{"title":"Příprava velikonoční večeře","range":"Lk 22,7–13","thoughts":[],"verses":[[7,"Přišel den nekvašených chlebů, kdy se měl zabíjet velikonoční beránek."],[8,"Ježíš poslal Petra a Jana se slovy: „Jděte a připravte nám velikonočního beránka, abychom ho mohli jíst.“"],[9,"Zeptali se ho: „Kde chceš, abychom ho připravili?“"],[10,"Odpověděl jim: „Až vejdete do města, potká vás muž nesoucí džbán vody. Jděte za ním do domu, do kterého vstoupí."],[11,"Majiteli domu řekněte: ‚Mistr se tě ptá: Kde je místnost, v níž budu jíst velikonočního beránka se svými učedníky?‘"],[12,"Ukáže vám velkou zařízenou horní místnost. Tam všechno připravte.“"],[13,"Odešli a našli všechno tak, jak jim řekl. Připravili tedy velikonočního beránka."]]},{"title":"Poslední večeře","range":"Lk 22,14–23","thoughts":[],"verses":[[14,"Když přišla hodina, Ježíš usedl ke stolu a apoštolové s ním."],[15,"Řekl jim: „Velmi jsem toužil jíst s vámi tohoto velikonočního beránka dříve, než budu trpět."],[16,"Říkám vám totiž, že ho už nebudu jíst, dokud se nenaplní v Božím království.“"],[17,"Potom vzal kalich, vzdal díky a řekl: „Vezměte ho a rozdělte mezi sebou."],[18,"Říkám vám totiž, že od této chvíle už nebudu pít z plodu vinné révy, dokud nepřijde Boží království.“"],[19,"Potom vzal chléb, vzdal díky, lámal ho a dával jim se slovy: „Toto je mé tělo, které se za vás dává. To dělejte na mou památku.“"],[20,"Stejně po večeři vzal i kalich a řekl: „Tento kalich je nová smlouva v mé krvi, která se za vás prolévá."],[21,"Ale podívejte, ruka toho, kdo mě zrazuje, je se mnou u stolu."],[22,"Syn člověka sice odchází tak, jak bylo určeno, ale běda člověku, který ho zrazuje.“"],[23,"A oni se začali mezi sebou dohadovat, kdo z nich by to mohl udělat."]]},{"title":"Kdo je největší","range":"Lk 22,24–30","thoughts":[],"verses":[[24,"Vznikl mezi nimi také spor o to, kdo z nich je považován za největší."],[25,"Ježíš jim řekl: „Králové národů nad nimi panují a ti, kdo nad nimi mají moc, si nechávají říkat dobrodinci."],[26,"Vy však ne tak. Kdo je mezi vámi největší, ať je jako nejmenší, a kdo vede, ať je jako ten, kdo slouží."],[27,"Kdo je totiž větší: ten, kdo sedí u stolu, nebo ten, kdo obsluhuje? Není to ten, kdo sedí u stolu? Já jsem však mezi vámi jako ten, kdo slouží."],[28,"Vy jste se mnou vytrvali v mých zkouškách."],[29,"A já vám svěřuji království, jako je můj Otec svěřil mně,"],[30,"abyste jedli a pili u mého stolu v mém království a seděli na trůnech a soudili dvanáct izraelských kmenů.“"]]},{"title":"Ježíš předpovídá Petrovo zapření","range":"Lk 22,31–38","thoughts":[],"verses":[[31,"Pán řekl: „Šimone, Šimone, satan si vyžádal, aby vás mohl tříbit jako pšenici."],[32,"Já jsem však prosil za tebe, aby tvá víra nezanikla. A ty, až se obrátíš, posiluj své bratry.“"],[33,"Petr mu řekl: „Pane, jsem připraven jít s tebou do vězení i na smrt.“"],[34,"Ježíš odpověděl: „Petře, říkám ti, že dnes kohout nezakokrhá, dokud třikrát nezapřeš, že mě znáš.“"],[35,"Potom jim řekl: „Když jsem vás posílal bez měšce, brašny a obuvi, chybělo vám něco?“ Odpověděli: „Nic.“"],[36,"Řekl jim: „Teď však, kdo má měšec, ať si ho vezme, stejně tak brašnu. A kdo nemá meč, ať prodá svůj plášť a koupí si ho."],[37,"Říkám vám totiž, že se na mně musí naplnit to, co je napsáno: ‚Byl započten mezi zločince.‘ To, co se týká mě, se totiž naplňuje.“"],[38,"Oni řekli: „Pane, tady jsou dva meče.“ Odpověděl jim: „To stačí.“"]]},{"title":"Ježíš na Olivové hoře","range":"Lk 22,39–46","thoughts":[],"verses":[[39,"Ježíš vyšel a jako obvykle zamířil na Olivovou horu. Učedníci šli za ním."],[40,"Když přišel na místo, řekl jim: „Modlete se, abyste nepodlehli pokušení.“"],[41,"Sám se od nich vzdálil asi na hod kamenem, poklekl a modlil se:"],[42,"„Otče, chceš-li, odejmi ode mě tento kalich. Ať se však nestane má vůle, ale tvá.“"],[43,"Tehdy se mu ukázal anděl z nebe a posiloval ho."],[44,"V úzkosti se modlil ještě usilovněji a jeho pot byl jako kapky krve stékající na zem."],[45,"Když vstal od modlitby a přišel k učedníkům, našel je spící zármutkem."],[46,"Řekl jim: „Proč spíte? Vstaňte a modlete se, abyste nepodlehli pokušení.“"]]},{"title":"Ježíšovo zatčení","range":"Lk 22,47–53","thoughts":[],"verses":[[47,"Ještě když mluvil, přišel zástup. V jeho čele šel Jidáš, jeden z Dvanácti, a přiblížil se k Ježíšovi, aby ho políbil."],[48,"Ježíš mu řekl: „Jidáši, polibkem zrazuješ Syna člověka?“"],[49,"Když ti, kdo byli s Ježíšem, viděli, k čemu se schyluje, zeptali se: „Pane, máme udeřit mečem?“"],[50,"Jeden z nich udeřil služebníka velekněze a uťal mu pravé ucho."],[51,"Ježíš však řekl: „Nechte toho!“ Dotkl se jeho ucha a uzdravil ho."],[52,"Ježíš řekl velekněžím, velitelům chrámové stráže a starším, kteří proti němu přišli: „Vyšli jste na mě s meči a holemi jako na lupiče."],[53,"Každý den jsem byl s vámi v chrámu, a nevztáhli jste na mě ruce. Ale toto je vaše hodina a moc temnoty.“"]]},{"title":"Petr zapírá Ježíše","range":"Lk 22,54–62","thoughts":[],"verses":[[54,"Ježíše zatkli, odvedli a přivedli do domu velekněze. Petr ho zpovzdálí následoval."],[55,"Uprostřed nádvoří rozdělali oheň a posadili se kolem něj. Petr si sedl mezi ně."],[56,"Jedna služka ho uviděla sedět u ohně, pozorně si ho prohlédla a řekla: „I tenhle byl s ním.“"],[57,"Petr to však zapřel: „Ženo, já ho neznám.“"],[58,"Za chvíli ho uviděl někdo jiný a řekl: „Ty jsi také jeden z nich.“ Petr odpověděl: „Člověče, nejsem.“"],[59,"Asi po hodině někdo další důrazně tvrdil: „Opravdu, i tento byl s ním. Vždyť je také Galilejec.“"],[60,"Petr řekl: „Člověče, nevím, o čem mluvíš.“ A ještě když mluvil, zakokrhal kohout."],[61,"Pán se obrátil a podíval se na Petra. Petr si vzpomněl na Pánova slova: „Dříve než dnes kohout zakokrhá, třikrát mě zapřeš.“"],[62,"Petr vyšel ven a hořce se rozplakal."]]},{"title":"Ježíš před radou","range":"Lk 22,63–71","thoughts":[],"verses":[[63,"Muži, kteří Ježíše hlídali, se mu posmívali a bili ho."],[64,"Zakryli mu oči, bili ho do tváře a ptali se: „Prorokuj, kdo tě udeřil?“"],[65,"A říkali proti němu ještě mnoho dalších urážek."],[66,"Když se rozednilo, sešli se starší lidu, velekněží a učitelé Zákona a odvedli Ježíše před svou radu."],[67,"Řekli mu: „Jsi-li Mesiáš, pověz nám to.“ Ježíš odpověděl: „Když vám to řeknu, neuvěříte."],[68,"A když se vás zeptám, neodpovíte mi ani mě nepropustíte."],[69,"Od této chvíle však bude Syn člověka sedět po pravici Boží moci.“"],[70,"Všichni se zeptali: „Ty jsi tedy Boží Syn?“ Odpověděl jim: „Vy sami říkáte, že jsem.“"],[71,"Oni řekli: „Nač ještě potřebujeme svědectví? Vždyť jsme to sami slyšeli z jeho úst.“"]]}];

LUKE_SECTIONS["23"] = [{"title":"Ježíš před Pilátem","range":"Lk 23,1–5","thoughts":[],"verses":[[1,"Potom celé shromáždění povstalo a odvedlo Ježíše k Pilátovi."],[2,"Začali ho obviňovat: „Zjistili jsme, že tento člověk rozvrací náš lid, zakazuje platit daně císaři a prohlašuje o sobě, že je Mesiáš, král.“"],[3,"Pilát se ho zeptal: „Ty jsi židovský král?“ Ježíš odpověděl: „Ty to říkáš.“"],[4,"Pilát řekl velekněžím a zástupům: „Na tomto člověku nenalézám žádnou vinu.“"],[5,"Oni však naléhali: „Svým učením pobuřuje lid po celém Judsku. Začal v Galileji a došel až sem.“"]]},{"title":"Ježíš před Herodem","range":"Lk 23,6–12","thoughts":[],"verses":[[6,"Když Pilát uslyšel o Galileji, zeptal se, zda je ten člověk Galilejec."],[7,"Když zjistil, že Ježíš patří pod Herodovu pravomoc, poslal ho k Herodovi, který byl v těch dnech také v Jeruzalémě."],[8,"Herodes měl z Ježíšova příchodu velikou radost. Už dlouho ho chtěl vidět, protože o něm mnoho slyšel, a doufal, že ho uvidí udělat nějaký zázrak."],[9,"Kladl mu mnoho otázek, ale Ježíš mu neodpověděl ani slovo."],[10,"Velekněží a učitelé Zákona tam stáli a prudce ho obviňovali."],[11,"Herodes se svými vojáky jím pohrdal a posmíval se mu. Oblékli ho do nádherného světlého roucha a poslali zpět k Pilátovi."],[12,"Právě toho dne se Pilát a Herodes spřátelili; předtím mezi nimi panovalo nepřátelství."]]},{"title":"Ježíš odsouzen k smrti","range":"Lk 23,13–25","thoughts":[],"verses":[[13,"Pilát svolal velekněze, přední muže i lid"],[14,"a řekl jim: „Přivedli jste mi tohoto člověka jako někoho, kdo svádí lid. Já jsem ho před vámi vyslechl a nenašel jsem na něm žádnou vinu z toho, z čeho ho obviňujete."],[15,"Ani Herodes nic nenašel, protože ho poslal zpět k nám. Je zřejmé, že neudělal nic, za co by zasluhoval smrt."],[16,"Dám ho tedy potrestat a potom ho propustím.“"],[17,"O svátku jim totiž musel propouštět jednoho vězně."],[18,"Celý zástup však vykřikl: „Pryč s ním! Propusť nám Barabáše!“"],[19,"Barabáš byl uvězněn za vzpouru ve městě a za vraždu."],[20,"Pilát k nim znovu promluvil, protože chtěl Ježíše propustit."],[21,"Oni však křičeli: „Ukřižuj ho! Ukřižuj ho!“"],[22,"Potřetí jim řekl: „Co zlého udělal? Nenašel jsem na něm nic, za co by zasluhoval smrt. Dám ho tedy potrestat a propustím.“"],[23,"Oni však dál naléhali hlasitým křikem a žádali, aby byl ukřižován. Jejich křik i hlasy velekněží sílily."],[24,"Pilát nakonec rozhodl, že jejich žádosti vyhoví."],[25,"Propustil jim muže uvězněného za vzpouru a vraždu, o kterého žádali, a Ježíše vydal jejich vůli."]]},{"title":"Cesta na Golgotu","range":"Lk 23,26–32","thoughts":[],"verses":[[26,"Když Ježíše odváděli, chytili Šimona z Kyrény, který se vracel z pole, a položili na něj kříž, aby ho nesl za Ježíšem."],[27,"Za Ježíšem šel veliký zástup lidu i žen, které nad ním plakaly a naříkaly."],[28,"Ježíš se k nim obrátil a řekl: „Jeruzalémské dcery, neplačte nade mnou. Plačte raději nad sebou a nad svými dětmi."],[29,"Přicházejí totiž dny, kdy lidé řeknou: ‚Blaze neplodným, ženám, které nerodily, a prsům, které nekojily.‘"],[30,"Tehdy začnou říkat horám: ‚Padněte na nás!‘ a pahorkům: ‚Přikryjte nás!‘"],[31,"Jestliže se toto děje se zeleným dřevem, co se teprve stane se suchým?“"],[32,"Spolu s Ježíšem vedli k popravě také dva zločince."]]},{"title":"Ukřižování","range":"Lk 23,33–43","thoughts":[],"verses":[[33,"Když přišli na místo zvané Lebka, ukřižovali tam Ježíše i oba zločince, jednoho po jeho pravici a druhého po levici."],[34,"Ježíš řekl: „Otče, odpusť jim, protože nevědí, co dělají.“ Potom si losem rozdělili jeho šaty."],[35,"Lid stál a díval se. Přední muži se mu posmívali: „Jiným pomáhal, ať teď pomůže sám sobě, jestliže je Mesiáš, Boží vyvolený.“"],[36,"Posmívali se mu i vojáci. Přicházeli k němu a podávali mu ocet"],[37,"se slovy: „Jestliže jsi židovský král, zachraň sám sebe.“"],[38,"Nad ním byl také nápis v řečtině, latině a hebrejštině: „Toto je židovský král.“"],[39,"Jeden ze zločinců, kteří viseli na kříži, se mu rouhal: „Jestliže jsi Mesiáš, zachraň sebe i nás!“"],[40,"Druhý ho však napomenul: „Ty se ani Boha nebojíš? Vždyť jsi odsouzen ke stejnému trestu."],[41,"My jsme odsouzeni spravedlivě a dostáváme, co si za své činy zasloužíme. On však neudělal nic zlého.“"],[42,"Potom řekl Ježíšovi: „Pane, vzpomeň si na mě, až přijdeš do svého království.“"],[43,"Ježíš mu řekl: „Amen, říkám ti: Dnes budeš se mnou v ráji.“"]]},{"title":"Ježíšova smrt","range":"Lk 23,44–49","thoughts":[],"verses":[[44,"Bylo kolem poledne a po celé zemi nastala tma až do tří hodin odpoledne."],[45,"Slunce se zatmělo a chrámová opona se roztrhla uprostřed."],[46,"Ježíš hlasitě zvolal: „Otče, do tvých rukou svěřuji svého ducha.“ Po těch slovech zemřel."],[47,"Když setník viděl, co se stalo, oslavoval Boha a řekl: „Tento člověk byl opravdu spravedlivý.“"],[48,"Všechny zástupy, které se přišly na tuto podívanou dívat, se po tom, co viděly, vracely a bily se do prsou."],[49,"Všichni Ježíšovi známí stáli opodál a dívali se. Byly tam i ženy, které ho následovaly z Galileje."]]},{"title":"Ježíšův pohřeb","range":"Lk 23,50–56","thoughts":[],"verses":[[50,"Byl tam muž jménem Josef, člen rady, dobrý a spravedlivý člověk."],[51,"Nesouhlasil s rozhodnutím ani jednáním ostatních. Pocházel z judského města Arimatie a také on očekával Boží království."],[52,"Šel k Pilátovi a požádal ho o Ježíšovo tělo."],[53,"Sňal je z kříže, zavinul do plátna a uložil do hrobu vytesaného ve skále, v němž ještě nikdo nebyl pohřben."],[54,"Byl den přípravy a začínala sobota."],[55,"Ženy, které přišly s Ježíšem z Galileje, šly za Josefem a prohlédly si hrob i způsob, jakým bylo Ježíšovo tělo uloženo."],[56,"Potom se vrátily a připravily vonné látky a masti. V sobotu však podle přikázání odpočívaly."]]}];

LUKE_SECTIONS["24"] = [{"title":"Prázdný hrob","range":"Lk 24,1–12","thoughts":[],"verses":[[1,"Prvního dne týdne přišly ženy velmi časně ráno k hrobu a nesly vonné látky, které připravily. Některé další ženy šly s nimi."],[2,"Našly kámen odvalený od hrobu."],[3,"Vešly dovnitř, ale tělo Pána Ježíše nenašly."],[4,"Když nad tím bezradně stály, objevili se u nich dva muži v zářivém oděvu."],[5,"Ženy se polekaly a sklonily tváře k zemi. Muži jim řekli: „Proč hledáte živého mezi mrtvými?"],[6,"Není tady, vstal z mrtvých. Vzpomeňte si, co vám říkal, když byl ještě v Galileji:"],[7,"‚Syn člověka musí být vydán do rukou hříšných lidí, být ukřižován a třetího dne vstát z mrtvých.‘“"],[8,"Tehdy si vzpomněly na jeho slova."],[9,"Vrátily se od hrobu a všechno oznámily Jedenácti i všem ostatním."],[10,"Byly to Marie Magdaléna, Jana a Marie, matka Jakubova, a další ženy s nimi. Ty o tom vyprávěly apoštolům."],[11,"Jim však jejich slova připadala jako nesmysl a nevěřili jim."],[12,"Petr ale vstal a běžel k hrobu. Naklonil se dovnitř a uviděl tam jen plátna. Odešel a sám se divil tomu, co se stalo."]]},{"title":"Cesta do Emauz","range":"Lk 24,13–35","thoughts":[],"verses":[[13,"Téhož dne šli dva z nich do vesnice jménem Emauzy, vzdálené od Jeruzaléma šedesát honů."],[14,"Cestou spolu mluvili o všem, co se stalo."],[15,"Když o tom rozmlouvali a společně to probírali, přiblížil se k nim sám Ježíš a šel s nimi."],[16,"Jejich oči však byly zastřeny, takže ho nepoznali."],[17,"Zeptal se jich: „O čem spolu cestou mluvíte a proč jste smutní?“"],[18,"Jeden z nich, jménem Kleofáš, mu odpověděl: „Ty jsi snad jediný návštěvník Jeruzaléma, který neví, co se tam v těchto dnech stalo?“"],[19,"Zeptal se: „Co?“ Odpověděli mu: „To, co se stalo s Ježíšem Nazaretským. Byl to prorok mocný skutkem i slovem před Bohem i před celým lidem."],[20,"Naši velekněží a přední muži ho vydali, aby byl odsouzen k smrti, a ukřižovali ho."],[21,"My jsme doufali, že právě on vykoupí Izrael. A navíc je dnes už třetí den od chvíle, kdy se to stalo."],[22,"Některé z našich žen nás ale překvapily. Brzy ráno byly u hrobu,"],[23,"a když jeho tělo nenašly, přišly s tím, že měly vidění andělů, kteří jim řekli, že žije."],[24,"Někteří z nás pak šli k hrobu a našli všechno přesně tak, jak ženy říkaly. Jeho však neviděli.“"],[25,"Ježíš jim řekl: „Jak jste nechápaví a jak pomalu věříte všemu, co řekli proroci!"],[26,"Což nemusel Mesiáš toto všechno vytrpět a potom vejít do své slávy?“"],[27,"A začal od Mojžíše a všech proroků a vysvětloval jim, co o něm říkají všechna Písma."],[28,"Když se přiblížili k vesnici, do které šli, Ježíš se tvářil, že chce pokračovat dál."],[29,"Oni ho však přemlouvali: „Zůstaň s námi. Už se stmívá a den se chýlí ke konci.“ Vešel tedy dovnitř, aby s nimi zůstal."],[30,"Když s nimi seděl u stolu, vzal chléb, požehnal ho, lámal a podával jim."],[31,"Vtom se jim otevřely oči a poznali ho. On jim však zmizel z očí."],[32,"Řekli si: „Což nám nehořelo srdce, když s námi cestou mluvil a otevíral nám Písma?“"],[33,"Ještě v tu hodinu vstali a vrátili se do Jeruzaléma. Našli tam shromážděných Jedenáct a ostatní, kteří byli s nimi."],[34,"Ti jim říkali: „Pán skutečně vstal z mrtvých a ukázal se Šimonovi!“"],[35,"A oni zase vyprávěli, co se stalo cestou a jak Ježíše poznali při lámání chleba."]]},{"title":"Ježíš se ukazuje učedníkům","range":"Lk 24,36–49","thoughts":[],"verses":[[36,"Když o tom mluvili, Ježíš se postavil uprostřed nich a řekl: „Pokoj vám.“"],[37,"Vyděsili se a plni strachu si mysleli, že vidí ducha."],[38,"Řekl jim: „Proč jste tak vyděšení? Proč ve vašem srdci vznikají pochybnosti?"],[39,"Podívejte se na mé ruce a nohy. Jsem to opravdu já. Dotkněte se mě a přesvědčte se. Duch přece nemá maso a kosti, jak vidíte, že mám já.“"],[40,"Když to řekl, ukázal jim ruce a nohy."],[41,"Protože stále ještě pro samou radost nemohli uvěřit a žasli, zeptal se jich: „Máte tady něco k jídlu?“"],[42,"Podali mu kus pečené ryby a plást medu."],[43,"Vzal si je a před nimi pojedl."],[44,"Potom jim řekl: „To je to, o čem jsem vám mluvil, ještě když jsem byl s vámi: Musí se naplnit všechno, co je o mně napsáno v Mojžíšově zákoně, v Prorocích a v Žalmech.“"],[45,"Tehdy jim otevřel mysl, aby rozuměli Písmům."],[46,"Řekl jim: „Je napsáno, že Mesiáš musí trpět a třetího dne vstát z mrtvých,"],[47,"a že v jeho jménu má být všem národům kázáno pokání a odpuštění hříchů, počínaje Jeruzalémem."],[48,"Vy jste toho svědky."],[49,"A já na vás pošlu to, co slíbil můj Otec. Vy však zůstaňte v Jeruzalémě, dokud nebudete oděni mocí shůry.“"]]},{"title":"Nanebevstoupení","range":"Lk 24,50–53","thoughts":[],"verses":[[50,"Potom je vyvedl až k Betanii. Zvedl ruce a požehnal jim."],[51,"A když jim žehnal, vzdálil se od nich a byl nesen do nebe."],[52,"Oni se mu poklonili a s velikou radostí se vrátili do Jeruzaléma."],[53,"Stále byli v chrámě, chválili Boha a dobrořečili mu. Amen."]]}];

